import React, { useState, useEffect } from 'react';
import { Garment, GarmentType, GeminiOutfitResponse, Post, ChatConversation, Message } from './types';
import { GarmentCard } from './components/GarmentCard';
import { OutfitResult } from './components/OutfitResult';
import { SocialPost } from './components/SocialPost';
import { ChatPanel } from './components/ChatPanel';
import { generateOutfitsFromImages } from './services/geminiService';

const MOCK_POSTS: Post[] = [
  {
    id: 'p1',
    user: { name: 'Thanh Hằng', level: 'Elite Fashionista', avatar: '' },
    time: '2 giờ trước',
    description: 'Một buổi sáng nắng đẹp tại trung tâm Quận 1. Set đồ này mang lại cảm giác cực kỳ thoải mái nhưng vẫn đủ lịch sự cho buổi họp khách hàng tại Workshop Coffee.',
    topImage: 'https://images.unsplash.com/photo-1598033129183-c4f50c717658?q=80&w=500&auto=format&fit=crop',
    bottomImage: 'https://images.unsplash.com/photo-1541099649105-f69ad21f3246?q=80&w=500&auto=format&fit=crop',
    location: '📍 The Workshop Coffee – Quận 1, TP.HCM',
    tags: ['OfficeStyle', 'Minimalism', 'SaigonLife'],
    transactionType: 'Thanh lý',
    stats: { likes: 124, comments: 12 },
    sampleComments: [
      { id: 'c1', userName: 'Minh Tú', content: 'Set này sang xịn mịn luôn chị ơi!' },
      { id: 'c2', userName: 'Quốc Anh', content: 'Xin info cái quần với ạ.' }
    ]
  },
  {
    id: 'p2',
    user: { name: 'Hoàng Long', level: 'Street Explorer', avatar: '' },
    time: '5 giờ trước',
    description: 'Đà Lạt sáng nay lạnh 15 độ, phối nhanh con bomber với quần túi hộp để đi săn mây. Vibe này đúng chất High Street luôn anh em nhỉ?',
    topImage: 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?q=80&w=500&auto=format&fit=crop',
    bottomImage: 'https://images.unsplash.com/photo-1620799140408-edc6dcb6d633?q=80&w=500&auto=format&fit=crop',
    location: '📍 Hồ Xuân Hương – Đà Lạt',
    tags: ['Streetwear', 'DalatTrip', 'WinterVibe', 'OOTD'],
    transactionType: 'Thuê',
    stats: { likes: 89, comments: 5 },
    sampleComments: [
      { id: 'c3', userName: 'Linh Chi', content: 'Dalat đi mùa này là nhất rồi.' }
    ]
  },
  {
    id: 'p3',
    user: { name: 'Bảo Thy', level: 'Vintage Lover', avatar: '' },
    time: 'Hôm qua',
    description: 'Lạc vào không gian nghệ thuật với phong cách hoài cổ. Chiếc áo sơ mi lụa kết hợp với chân váy midi tạo nên tổng thể rất nghệ thuật.',
    topImage: 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?q=80&w=500&auto=format&fit=crop',
    bottomImage: 'https://images.unsplash.com/photo-1583496661160-fb5886a0aaaa?q=80&w=500&auto=format&fit=crop',
    location: '📍 Bảo tàng Mỹ thuật – TP.HCM',
    tags: ['Vintage', 'ArtGallery', 'ClassicStyle'],
    stats: { likes: 215, comments: 18 },
    sampleComments: []
  }
];

const INITIAL_CHATS: ChatConversation[] = [
  {
    id: 'c1',
    userName: 'Thanh Hằng',
    userLevel: 'Elite Fashionista',
    avatar: 'TH',
    lastMessage: 'Áo đó còn size S không bạn nhỉ?',
    messages: [
      { id: 'm1', text: 'Chào Hằng, mình thấy bạn đăng thanh lý set đồ công sở.', time: '10:00', isMe: true },
      { id: 'm2', text: 'Chào bạn! Đúng rồi ạ, set đó mình mới mặc 1 lần thôi.', time: '10:02', isMe: false },
      { id: 'm3', text: 'Áo đó còn size S không bạn nhỉ?', time: '10:05', isMe: false },
    ]
  },
  {
    id: 'c2',
    userName: 'Hoàng Long',
    userLevel: 'Street Explorer',
    avatar: 'HL',
    lastMessage: 'OK, chốt thuê set đồ đi Đà Lạt nhé!',
    messages: [
      { id: 'm4', text: 'OK, chốt thuê set đồ đi Đà Lạt nhé!', time: 'Vừa xong', isMe: false }
    ]
  },
  {
    id: 'c3',
    userName: 'Bảo Thy',
    userLevel: 'Vintage Lover',
    avatar: 'BT',
    lastMessage: 'Cảm ơn bạn đã tư vấn phối đồ nha.',
    messages: []
  }
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'generate' | 'profile'>('home');
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [tops, setTops] = useState<Garment[]>([]);
  const [bottoms, setBottoms] = useState<Garment[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GeminiOutfitResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);

  const [conversations, setConversations] = useState<ChatConversation[]>(INITIAL_CHATS);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const handleSendMessage = (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        if (messageIdToEdit) {
          return {
            ...chat,
            messages: chat.messages.map(m => m.id === messageIdToEdit ? { ...m, text, isEdited: true } : m)
          };
        } else {
          const newMessage: Message = {
            id: Math.random().toString(36).substr(2, 9),
            text,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMe: true,
            replyTo
          };
          return {
            ...chat,
            lastMessage: text,
            messages: [...chat.messages, newMessage]
          };
        }
      }
      return chat;
    }));
  };

  const handleRecallMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => m.id === messageId ? { ...m, isRecalled: true, text: 'Tin nhắn đã được thu hồi' } : m)
        };
      }
      return chat;
    }));
  };

  const handleDeleteMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.filter(m => m.id !== messageId)
        };
      }
      return chat;
    }));
  };

  const handleReactToMessage = (chatId: string, messageId: string, reaction: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => {
            if (m.id === messageId) {
              // Toggle reaction: if same as before, remove it
              return { ...m, reaction: m.reaction === reaction ? undefined : reaction };
            }
            return m;
          })
        };
      }
      return chat;
    }));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: GarmentType) => {
    const files = e.target.files;
    if (!files) return;
    setError(null);
    (Array.from(files) as File[]).forEach(file => {
      if (file.size > 5 * 1024 * 1024) {
        setError("Ảnh quá lớn! Vui lòng chọn ảnh dưới 5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const newGarment: Garment = {
          id: Math.random().toString(36).substr(2, 9),
          type,
          name: file.name,
          image: reader.result as string
        };
        if (type === GarmentType.TOP) {
          setTops(prev => [...prev, newGarment]);
        } else {
          setBottoms(prev => [...prev, newGarment]);
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const removeGarment = (id: string, type: GarmentType) => {
    if (type === GarmentType.TOP) {
      setTops(prev => prev.filter(g => g.id !== id));
    } else {
      setBottoms(prev => prev.filter(g => g.id !== id));
    }
  };

  const handleGenerate = async () => {
    if (tops.length === 0 || bottoms.length === 0) {
      setError("Vui lòng thêm ít nhất 1 ảnh áo và 1 ảnh quần.");
      return;
    }
    setIsGenerating(true);
    setError(null);
    try {
      const response = await generateOutfitsFromImages(tops, bottoms);
      if (response && response.outfits && response.outfits.length > 0) {
        setResult(response);
      } else {
        setError("AI không thể phân tích được ảnh. Hãy thử ảnh rõ nét hơn!");
      }
    } catch (err) {
      setError("Lỗi kết nối Server AI. Vui lòng thử lại sau!");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderHome = () => (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className="relative h-48 bg-brand-red dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-8 text-white shadow-xl border-b-4 border-brand-gold/50">
        <div className="relative z-10">
          <h2 className="text-2xl font-black mb-2 text-brand-goldLight">Chào Fashionista!</h2>
          <p className="text-xs text-white/90 max-w-[200px] leading-relaxed font-semibold">Khám phá phong cách thượng lưu của riêng bạn ngay hôm nay.</p>
        </div>
        <i className="fa-solid fa-sparkles absolute top-6 right-8 text-4xl text-brand-gold animate-pulse"></i>
        <div className="absolute -bottom-10 -right-10 opacity-10 rotate-12 text-brand-gold">
          <i className="fa-solid fa-shirt text-[150px]"></i>
        </div>
      </div>
      <section className="space-y-4">
        <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest px-1">Gợi ý phong cách</h3>
        <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x">
          {['Minimalism', 'Vintage', 'Streetwear', 'Chic'].map((style, i) => (
            <div key={i} className="flex-shrink-0 w-36 h-44 bg-white dark:bg-slate-900 rounded-[2rem] p-5 border border-brand-gold/20 dark:border-slate-800 flex flex-col justify-end shadow-sm snap-center">
              <span className="text-[10px] font-black text-brand-gold uppercase">Style</span>
              <p className="font-bold text-brand-red dark:text-slate-100">{style}</p>
            </div>
          ))}
        </div>
      </section>
      <section className="space-y-6">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Cộng đồng SmartStylist</h3>
          <button className="text-[10px] font-black text-brand-gold uppercase tracking-tighter">Xem thêm</button>
        </div>
        <div className="space-y-8">
          {MOCK_POSTS.map(post => (
            <SocialPost key={post.id} post={post} />
          ))}
        </div>
      </section>
    </div>
  );

  const renderGenerate = () => (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-10">
      {!result ? (
        <>
          <section className="space-y-4">
            <div className="flex items-center justify-between px-1">
              <h3 className="font-black text-brand-red dark:text-slate-200 flex items-center gap-2 uppercase text-xs tracking-wider">
                <i className="fa-solid fa-shirt text-brand-gold"></i> Áo (Tops)
              </h3>
              <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full active:scale-95 transition-all cursor-pointer border border-brand-gold/30">
                + THÊM
                <input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.TOP)} />
              </label>
            </div>
            {tops.length === 0 ? (
              <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 dark:border-slate-800 rounded-[2.5rem] h-36 flex flex-col items-center justify-center text-slate-400 gap-2">
                <i className="fa-solid fa-camera text-2xl opacity-20 text-brand-red"></i>
                <p className="text-[9px] font-bold uppercase tracking-widest text-brand-red/40">Chưa có dữ liệu áo</p>
              </div>
            ) : (
              <div className="grid grid-cols-3 gap-3">
                {tops.map(g => (
                  <GarmentCard key={g.id} garment={g} onRemove={(id) => removeGarment(id, GarmentType.TOP)} />
                ))}
              </div>
            )}
          </section>
          <section className="space-y-4">
            <div className="flex items-center justify-between px-1">
              <h3 className="font-black text-brand-red dark:text-slate-200 flex items-center gap-2 uppercase text-xs tracking-wider">
                <i className="fa-solid fa-person-half-dress text-brand-gold"></i> Quần & Váy
              </h3>
              <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full active:scale-95 transition-all cursor-pointer border border-brand-gold/30">
                + THÊM
                <input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.BOTTOM)} />
              </label>
            </div>
            {bottoms.length === 0 ? (
              <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 dark:border-slate-800 rounded-[2.5rem] h-36 flex flex-col items-center justify-center text-slate-400 gap-2">
                <i className="fa-solid fa-camera text-2xl opacity-20 text-brand-red"></i>
                <p className="text-[9px] font-bold uppercase tracking-widest text-brand-red/40">Chưa có dữ liệu quần</p>
              </div>
            ) : (
              <div className="grid grid-cols-3 gap-3">
                {bottoms.map(g => (
                  <GarmentCard key={g.id} garment={g} onRemove={(id) => removeGarment(id, GarmentType.BOTTOM)} />
                ))}
              </div>
            )}
          </section>
          <div className="pt-4">
            <button 
              onClick={handleGenerate}
              disabled={isGenerating || tops.length === 0 || bottoms.length === 0}
              className="w-full h-16 bg-brand-red text-brand-goldLight rounded-[1.5rem] font-black shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50 border-2 border-brand-gold/40"
            >
              {isGenerating ? <i className="fa-solid fa-circle-notch animate-spin text-brand-gold"></i> : <><i className="fa-solid fa-wand-magic-sparkles text-brand-gold"></i> PHỐI ĐỒ NGAY</>}
            </button>
          </div>
        </>
      ) : (
        <div className="space-y-12 pb-10">
          <div className="flex items-center justify-between px-1">
             <h3 className="text-xl font-black text-brand-red dark:text-slate-100 tracking-tight">Gợi ý dành riêng cho bạn</h3>
             <button onClick={() => setResult(null)} className="text-[10px] font-black text-white bg-brand-red px-4 py-2 rounded-full uppercase tracking-widest border border-brand-gold/30 shadow-md">
               <i className="fa-solid fa-rotate-left mr-1"></i> Làm lại
             </button>
          </div>
          {result.outfits.map((outfit, idx) => (
            <OutfitResult key={idx} outfit={outfit} top={tops[outfit.topIndex]} bottom={bottoms[outfit.bottomIndex]} />
          ))}
        </div>
      )}
    </div>
  );

  const renderProfile = () => (
    <div className="space-y-8 animate-in slide-in-from-left-4 duration-500 pb-10">
      <div className="flex flex-col items-center py-8 space-y-4">
        <div className="w-24 h-24 bg-brand-red rounded-[2.5rem] flex items-center justify-center text-3xl text-brand-gold border-4 border-brand-gold/30 shadow-2xl">
           <i className="fa-solid fa-user-ninja"></i>
        </div>
        <div className="text-center">
          <h2 className="text-xl font-black text-brand-red dark:text-slate-100 uppercase tracking-tight">Fashionista VN</h2>
          <p className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.2em] bg-brand-red px-3 py-1 rounded-full inline-block mt-2">Level 1 Discoverer</p>
        </div>
      </div>
      <div className="space-y-3 px-2">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between shadow-sm transition-colors">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-brand-red/10 dark:bg-indigo-900/30 rounded-xl flex items-center justify-center text-brand-red">
              <i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i>
            </div>
            <span className="font-bold text-brand-red dark:text-slate-200">Giao diện tối</span>
          </div>
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className={`w-12 h-6 rounded-full transition-all relative ${isDarkMode ? 'bg-brand-red' : 'bg-slate-300'}`}
          >
            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isDarkMode ? 'left-7' : 'left-1'}`}></div>
          </button>
        </div>
        {[
          { label: 'Lịch sử phối đồ', icon: 'fa-clock-rotate-left' },
          { label: 'Địa điểm đã lưu', icon: 'fa-bookmark' },
          { label: 'Cài đặt tài khoản', icon: 'fa-gear' },
          { label: 'Trợ giúp & Phản hồi', icon: 'fa-circle-question' }
        ].map((item, i) => (
          <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer shadow-sm">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-brand-cream dark:bg-slate-800 rounded-xl flex items-center justify-center text-brand-gold shadow-inner">
                <i className={`fa-solid ${item.icon}`}></i>
              </div>
              <span className="font-bold text-brand-red dark:text-slate-200">{item.label}</span>
            </div>
            <i className="fa-solid fa-chevron-right text-[10px] text-brand-gold/70"></i>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-[100dvh] max-w-md mx-auto bg-brand-cream dark:bg-slate-950 relative shadow-2xl overflow-hidden font-sans transition-colors duration-300">
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center justify-between border-b-2 border-brand-gold/40 sticky top-0 z-30 transition-colors shadow-lg">
        <h1 className="text-2xl font-black text-brand-goldLight tracking-tighter uppercase italic drop-shadow-sm">SmartStylist</h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsChatOpen(true)} className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight text-sm border border-brand-gold/40 shadow-inner active:scale-90 transition-transform">
              <i className="fa-solid fa-comment-dots"></i>
           </button>
           <div className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight text-sm border border-brand-gold/40 shadow-inner">
              <i className="fa-solid fa-bell"></i>
           </div>
        </div>
      </header>
      <main className="flex-1 overflow-y-auto px-6 pt-6 pb-4 smooth-scroll overscroll-contain scrollbar-hide">
        {activeTab === 'home' && renderHome()}
        {activeTab === 'generate' && renderGenerate()}
        {activeTab === 'profile' && renderProfile()}
        <div className="h-24"></div>
      </main>
      {error && (
        <div className="absolute top-24 left-6 right-6 z-50 p-4 bg-brand-red text-white rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300 border border-brand-gold/40">
          <i className="fa-solid fa-circle-exclamation text-brand-gold"></i>
          <p className="text-xs font-bold">{error}</p>
          <button onClick={() => setError(null)} className="ml-auto opacity-50"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
      <ChatPanel 
        isOpen={isChatOpen} 
        onClose={() => setIsChatOpen(false)} 
        conversations={conversations}
        onSendMessage={handleSendMessage}
        onRecallMessage={handleRecallMessage}
        onDeleteMessage={handleDeleteMessage}
        onReactToMessage={handleReactToMessage}
      />
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/95 dark:bg-slate-900/95 backdrop-blur-2xl border-t border-brand-gold/30 z-40 safe-pb transition-colors shadow-[0_-10px_20px_rgba(0,0,0,0.05)]">
        <div className="grid grid-cols-3 items-center h-20 px-4">
          <button onClick={() => setActiveTab('home')} className={`flex flex-col items-center justify-center gap-1 transition-all active:scale-90 ${activeTab === 'home' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400 dark:text-slate-600'}`}>
            <i className={`fa-solid fa-house-chimney text-xl ${activeTab === 'home' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">Trang chủ</span>
          </button>
          <div className="relative flex justify-center">
            <button onClick={() => setActiveTab('generate')} className={`w-14 h-14 bg-brand-red rounded-full flex items-center justify-center shadow-xl border-4 border-brand-gold/50 transition-all absolute -top-12 active:scale-95 ${activeTab === 'generate' ? 'scale-110' : ''}`}>
               <i className="fa-solid fa-wand-magic-sparkles text-brand-gold text-xl"></i>
            </button>
            <span className={`text-[9px] font-black uppercase tracking-tighter mt-8 ${activeTab === 'generate' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400 dark:text-slate-600'}`}>Phối đồ</span>
          </div>
          <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center justify-center gap-1 transition-all active:scale-90 ${activeTab === 'profile' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400 dark:text-slate-600'}`}>
            <i className={`fa-solid fa-user-large text-xl ${activeTab === 'profile' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">Tôi</span>
          </button>
        </div>
      </nav>
      {isGenerating && (
