        <div className="w-24 h-24 bg-brand-red rounded-[2.5rem] flex items-center justify-center text-3xl text-brand-gold border-4 border-brand-gold/30 shadow-2xl">
           <i className="fa-solid fa-user-ninja"></i>
        </div>
        <div className="text-center">
          <h2 className="text-xl font-black text-brand-red dark:text-slate-100 uppercase tracking-tight">Fashionista VN</h2>
          <p className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.2em] bg-brand-red px-3 py-1 rounded-full inline-block mt-2">Level 1 Discoverer</p>
        </div>
      </div>
      <div className="space-y-3 px-2">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between shadow-sm transition-colors">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-brand-red/10 dark:bg-indigo-900/30 rounded-xl flex items-center justify-center text-brand-red">
              <i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i>
            </div>
            <span className="font-bold text-brand-red dark:text-slate-200">Giao diện tối</span>
          </div>
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className={`w-12 h-6 rounded-full transition-all relative ${isDarkMode ? 'bg-brand-red' : 'bg-slate-300'}`}
          >
            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isDarkMode ? 'left-7' : 'left-1'}`}></div>
          </button>
        </div>
        {[
          { label: 'Lịch sử phối đồ', icon: 'fa-clock-rotate-left' },
          { label: 'Địa điểm đã lưu', icon: 'fa-bookmark' },
          { label: 'Cài đặt tài khoản', icon: 'fa-gear' },
          { label: 'Trợ giúp & Phản hồi', icon: 'fa-circle-question' }
        ].map((item, i) => (
          <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer shadow-sm">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-brand-cream dark:bg-slate-800 rounded-xl flex items-center justify-center text-brand-gold shadow-inner">
                <i className={`fa-solid ${item.icon}`}></i>
              </div>
              <span className="font-bold text-brand-red dark:text-slate-200">{item.label}</span>
            </div>
            <i className="fa-solid fa-chevron-right text-[10px] text-brand-gold/70"></i>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-[100dvh] max-w-md mx-auto bg-brand-cream dark:bg-slate-950 relative shadow-2xl overflow-hidden font-sans transition-colors duration-300">
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center justify-between border-b-2 border-brand-gold/40 sticky top-0 z-30 transition-colors shadow-lg">
        <h1 className="text-2xl font-black text-brand-goldLight tracking-tighter uppercase italic drop-shadow-sm">SmartStylist</h1>
        <div className="flex items-center gap-2">
           <button onClick={() => { setChatContextPost(null); setIsChatOpen(true); }} className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight text-sm border border-brand-gold/40 shadow-inner active:scale-90 transition-transform">
              <i className="fa-solid fa-comment-dots"></i>
           </button>
           <div className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight text-sm border border-brand-gold/40 shadow-inner">
              <i className="fa-solid fa-bell"></i>
           </div>
        </div>
      </header>
      <main className="flex-1 overflow-y-auto px-6 pt-6 pb-4 smooth-scroll overscroll-contain scrollbar-hide">
        {activeTab === 'home' && renderHome()}
        {activeTab === 'generate' && renderGenerate()}
        {activeTab === 'profile' && renderProfile()}
        <div className="h-24"></div>
      </main>
      {error && (
        <div className="absolute top-24 left-6 right-6 z-50 p-4 bg-brand-red text-white rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300 border border-brand-gold/40">
          <i className="fa-solid fa-circle-exclamation text-brand-gold"></i>
          <p className="text-xs font-bold">{error}</p>
          <button onClick={() => setError(null)} className="ml-auto opacity-50"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
      <ChatPanel 
        isOpen={isChatOpen} 
        onClose={() => { setIsChatOpen(false); setChatContextPost(null); }} 
        conversations={conversations}
        initialChatId={activeChatId}
        contextPost={chatContextPost}
        onSendMessage={handleSendMessage}
        onRecallMessage={handleRecallMessage}
        onDeleteMessage={handleDeleteMessage}
        onReactToMessage={handleReactToMessage}
      />
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/95 dark:bg-slate-900/95 backdrop-blur-2xl border-t border-brand-gold/30 z-40 safe-pb transition-colors shadow-[0_-10px_20px_rgba(0,0,0,0.05)]">
        <div className="grid grid-cols-3 items-center h-20 px-4">
          <button onClick={() => setActiveTab('home')} className={`flex flex-col items-center justify-center gap-1 transition-all active:scale-90 ${activeTab === 'home' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400 dark:text-slate-600'}`}>
            <i className={`fa-solid fa-house-chimney text-xl ${activeTab === 'home' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">Trang chủ</span>
          </button>
          <div className="relative flex justify-center">
            <button onClick={() => setActiveTab('generate')} className={`w-14 h-14 bg-brand-red rounded-full flex items-center justify-center shadow-xl border-4 border-brand-gold/50 transition-all absolute -top-12 active:scale-95 ${activeTab === 'generate' ? 'scale-110' : ''}`}>
               <i className="fa-solid fa-wand-magic-sparkles text-brand-gold text-xl"></i>
            </button>
            <span className={`text-[9px] font-black uppercase tracking-tighter mt-8 ${activeTab === 'generate' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400 dark:text-slate-600'}`}>Phối đồ</span>
          </div>
          <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center justify-center gap-1 transition-all active:scale-90 ${activeTab === 'profile' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400 dark:text-slate-600'}`}>
            <i className={`fa-solid fa-user-large text-xl ${activeTab === 'profile' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">Tôi</span>
          </button>
        </div>
      </nav>
      {isGenerating && (
        <div className="fixed inset-0 bg-brand-red/95 dark:bg-slate-950/95 backdrop-blur-md z-50 flex flex-col items-center justify-center p-8 text-center animate-in fade-in transition-colors">
          <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center mb-10 animate-bounce border-4 border-brand-gold">
            <i className="fa-solid fa-wand-magic-sparkles text-4xl text-brand-red"></i>
          </div>
          <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tighter">Thiết kế phong cách</h3>
          <p className="text-brand-goldLight text-sm font-semibold animate-pulse">Đang kiến tạo vẻ đẹp đẳng cấp cho bạn...</p>
        </div>
      )}
    </div>
  );
};

export default App;

