      </div>

      {/* Sample Comments */}
      {post.sampleComments.length > 0 && (
        <div className="px-6 pb-6 space-y-2">
          {post.sampleComments.map(comment => (
            <div key={comment.id} className="text-[10px] leading-relaxed">
              <span className="font-black text-brand-red dark:text-brand-gold mr-2 uppercase tracking-tighter">{comment.userName}</span>
              <span className="text-slate-600 dark:text-slate-400 font-medium">{comment.content}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ChatConversation, Message, Post } from '../types';

interface ChatPanelProps {
  isOpen: boolean;
  onClose: () => void;
  conversations: ChatConversation[];
  initialChatId?: string | null;
  contextPost?: Post | null;
  onSendMessage: (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => void;
  onRecallMessage: (chatId: string, messageId: string) => void;
  onDeleteMessage: (chatId: string, messageId: string) => void;
  onReactToMessage: (chatId: string, messageId: string, reaction: string) => void;
}

const REACTIONS = ['❤️', '🔥', '👍', '😂', '😮', '😢'];

export const ChatPanel: React.FC<ChatPanelProps> = ({ 
  isOpen, onClose, conversations, initialChatId, contextPost,
  onSendMessage, onRecallMessage, onDeleteMessage, onReactToMessage 
}) => {
  const [selectedChatId, setSelectedChatId] = useState<string | null>(null);
  const [inputValue, setInputValue] = useState('');
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [replyingToMessage, setReplyingToMessage] = useState<Message | null>(null);
  const [contextMenu, setContextMenu] = useState<{ x: number, y: number, msg: Message } | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (initialChatId) {
      setSelectedChatId(initialChatId);
    }
  }, [initialChatId]);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [selectedChatId, conversations]);

  if (!isOpen) return null;

  const selectedChat = conversations.find(c => c.id === selectedChatId) || null;

  const handleSend = () => {
    if (!inputValue.trim() || !selectedChatId) return;

    let replyData: Message['replyTo'] | undefined;
    if (replyingToMessage) {
      replyData = {
        userName: replyingToMessage.isMe ? "Tôi" : (selectedChat?.userName || "Người dùng"),
        text: replyingToMessage.text
      };
    }

    onSendMessage(selectedChatId, inputValue.trim(), editingMessageId || undefined, replyData);
    setInputValue('');
    setEditingMessageId(null);
    setReplyingToMessage(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSend();
  };

  const handleLongPress = (e: React.MouseEvent | React.TouchEvent, msg: Message) => {
    const x = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const y = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    longPressTimer.current = setTimeout(() => {
      if (!msg.isRecalled) {
        setContextMenu({ x, y, msg });
        if (window.navigator.vibrate) window.navigator.vibrate(50);
      }
    }, 500);
  };

  const cancelLongPress = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
  };

  const handleAction = (type: 'reply' | 'edit' | 'recall' | 'delete' | 'react', payload?: any) => {
    if (!contextMenu || !selectedChatId) return;
    const { msg } = contextMenu;

    switch (type) {
      case 'reply':
        setReplyingToMessage(msg);
        setEditingMessageId(null);
        break;
      case 'edit':
        setInputValue(msg.text);
        setEditingMessageId(msg.id);
        setReplyingToMessage(null);
        break;
      case 'recall':
        onRecallMessage(selectedChatId, msg.id);
        break;
      case 'delete':
        onDeleteMessage(selectedChatId, msg.id);
        break;
      case 'react':
        onReactToMessage(selectedChatId, msg.id, payload);
        break;
    }
    setContextMenu(null);
  };

  const getMenuStyles = () => {
    if (!contextMenu) return {};
    const menuWidth = 240;
    const menuHeight = 280;
    const screenWidth = window.innerWidth;
    const screenHeight = window.innerHeight;
    const margin = 20;
    let left = contextMenu.x - 20;
    let top = contextMenu.y - 20;
    if (left + menuWidth > screenWidth - margin) left = screenWidth - menuWidth - margin;
    if (left < margin) left = margin;
    if (top + menuHeight > screenHeight - margin - 80) top = contextMenu.y - menuHeight + 20;
    if (top < margin + 60) top = margin + 80;
    return { top, left };
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col bg-brand-cream dark:bg-slate-950 animate-in slide-in-from-right duration-300">
      {/* Context Menu Overlay */}
      {contextMenu && (
        <div className="fixed inset-0 z-[110] bg-black/40 backdrop-blur-[3px]" onClick={() => setContextMenu(null)}>
          <div 
            className="absolute bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] border border-brand-gold/30 p-1 min-w-[220px] animate-in zoom-in-95 duration-200"
            style={getMenuStyles()}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex justify-between items-center gap-1 p-5 mb-1">
              {REACTIONS.map(r => (
                <button key={r} onClick={() => handleAction('react', r)} className="text-2xl hover:scale-125 transition-transform duration-200">
                  {r}
                </button>
              ))}
            </div>
            <div className="h-[1px] bg-brand-gold/10 mx-5 mb-1"></div>
            <div className="flex flex-col p-2">
              <button onClick={() => handleAction('reply')} className="flex items-center gap-4 px-5 py-4 text-[11px] font-black text-brand-red dark:text-brand-gold uppercase hover:bg-brand-red/5 rounded-[1.5rem]">
                <i className="fa-solid fa-reply text-sm"></i> Trả lời
              </button>
              {contextMenu.msg.isMe && (
                <>
                  <button onClick={() => handleAction('edit')} className="flex items-center gap-4 px-5 py-4 text-[11px] font-black text-brand-red dark:text-brand-gold uppercase hover:bg-brand-red/5 rounded-[1.5rem]">
                    <i className="fa-solid fa-pen-to-square text-sm"></i> Chỉnh sửa
                  </button>
                  <button onClick={() => handleAction('recall')} className="flex items-center gap-4 px-5 py-4 text-[11px] font-black text-brand-red dark:text-brand-gold uppercase hover:bg-brand-red/5 rounded-[1.5rem]">
                    <i className="fa-solid fa-rotate-left text-sm"></i> Thu hồi
                  </button>
                </>
              )}
              <button onClick={() => handleAction('delete')} className={`flex items-center gap-4 px-5 py-4 text-[11px] font-black uppercase hover:bg-red-50 rounded-[1.5rem] ${contextMenu.msg.isMe ? 'text-orange-600' : 'text-brand-red'}`}>
                <i className="fa-solid fa-trash-can text-sm"></i> {contextMenu.msg.isMe ? 'Xóa vĩnh viễn' : 'Xóa phía tôi'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center gap-4 border-b-2 border-brand-gold/40 shadow-lg relative">
        <button onClick={selectedChat ? () => setSelectedChatId(null) : onClose} className="text-brand-goldLight text-xl">
          <i className={`fa-solid ${selectedChat ? 'fa-chevron-left' : 'fa-xmark'}`}></i>
        </button>
        <div className="flex-1">
          <h2 className="text-lg font-black text-brand-goldLight uppercase tracking-tight">{selectedChat ? selectedChat.userName : 'Hộp thư tin nhắn'}</h2>
          {selectedChat && <p className="text-[10px] text-brand-gold/70 font-bold uppercase leading-none">{selectedChat.userLevel} • Hoạt động</p>}
        </div>
      </header>

      {/* Content */}
      <main className="flex-1 overflow-y-auto p-4 scrollbar-hide">
        {!selectedChat ? (
          <div className="space-y-2">
            {conversations.map(chat => (
              <button key={chat.id} onClick={() => setSelectedChatId(chat.id)} className="w-full bg-white dark:bg-slate-900 p-5 rounded-[2rem] flex items-center gap-4 border border-brand-gold/10 dark:border-slate-800 active:scale-[0.98] transition-all shadow-sm">
                <div className="w-12 h-12 bg-brand-red rounded-2xl flex items-center justify-center text-brand-gold font-black border border-brand-gold/30 shadow-md">{chat.avatar}</div>
                <div className="flex-1 text-left overflow-hidden">
                  <div className="flex justify-between items-center mb-1">
                    <h4 className="font-black text-brand-red dark:text-slate-100 uppercase text-xs">{chat.userName}</h4>
                    <span className="text-[8px] text-slate-400">{chat.messages.length > 0 ? chat.messages[chat.messages.length - 1].time : ''}</span>
                  </div>
                  <p className="text-[10px] text-slate-500 dark:text-slate-400 truncate font-medium">{chat.lastMessage}</p>
                </div>
              </button>
            ))}
          </div>
        ) : (
          <div className="flex flex-col gap-4 pb-20">
            {/* Outfit Context Card */}
            {contextPost && contextPost.user.name === selectedChat.userName && (
              <div className="mx-2 mb-6 animate-in slide-in-from-top-4 duration-500">
                <div className="bg-white dark:bg-slate-900 rounded-[2rem] border-2 border-brand-gold/30 shadow-xl overflow-hidden flex flex-col">
                  <div className="p-3 flex items-center gap-4 bg-brand-gold/5 dark:bg-white/5">
                    <div className="flex gap-1">
                      <img src={contextPost.topImage} className="w-12 h-16 object-cover rounded-lg border border-brand-gold/20" alt="Top" />
                      <img src={contextPost.bottomImage} className="w-12 h-16 object-cover rounded-lg border border-brand-gold/20" alt="Bottom" />
                    </div>
                    <div className="flex-1 overflow-hidden">
                      <p className="text-[9px] font-black text-brand-gold uppercase tracking-widest mb-0.5">Đang quan tâm</p>
                      <p className="text-[11px] font-bold text-slate-800 dark:text-slate-100 truncate italic">"{contextPost.description.substring(0, 50)}..."</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => alert(`Bắt đầu quy trình ${contextPost.transactionType?.toLowerCase()}...`)}
                    className="w-full py-3 bg-brand-red text-brand-goldLight text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 active:bg-brand-red/90 transition-colors"
                  >
                    <i className="fa-solid fa-cart-shopping"></i>
                    {contextPost.transactionType === 'Thanh lý' ? 'MUA NGAY SET ĐỒ NÀY' : 'THUÊ NGAY SET ĐỒ NÀY'}
                  </button>
                </div>
              </div>
            )}

            <div className="text-center py-6">
              <div className="w-16 h-16 bg-brand-red rounded-[1.5rem] flex items-center justify-center text-brand-gold text-2xl font-black border-2 border-brand-gold/30 mx-auto shadow-xl mb-3">{selectedChat.avatar}</div>
              <p className="text-[10px] font-black text-brand-gold uppercase tracking-widest">{selectedChat.userLevel}</p>
              <p className="text-[9px] text-slate-400 mt-1 uppercase">Bắt đầu từ tháng 01/2025</p>
            </div>

            {selectedChat.messages.map(msg => (
              <div 
                key={msg.id} 
                className={`flex flex-col ${msg.isMe ? 'items-end' : 'items-start'}`}
                onMouseDown={(e) => handleLongPress(e, msg)}
                onMouseUp={cancelLongPress}
                onMouseLeave={cancelLongPress}
                onTouchStart={(e) => handleLongPress(e, msg)}
                onTouchEnd={cancelLongPress}
              >
                <div className={`relative max-w-[80%] p-4 rounded-[2rem] shadow-sm text-xs font-semibold transition-all ${
                  msg.isRecalled 
                    ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 italic border border-slate-200'
                    : msg.isMe 
                      ? 'bg-brand-red text-brand-goldLight rounded-tr-none border border-brand-gold/20' 
                      : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-tl-none border border-brand-gold/10'
                }`}>
                  {/* Quoted Message / Reply Tag */}
                  {msg.replyTo && !msg.isRecalled && (
                    <div className={`mb-2 p-2 rounded-xl text-[10px] border-l-2 border-brand-gold bg-black/5 dark:bg-white/5 opacity-80 overflow-hidden line-clamp-2 ${msg.isMe ? 'bg-white/10' : ''}`}>
                      <p className="font-black uppercase tracking-tighter text-[8px] mb-0.5">{msg.replyTo.userName}</p>
                      <p className="italic truncate">{msg.replyTo.text}</p>
                    </div>
                  )}

                  <p className="leading-relaxed">{msg.text}</p>

                  <div className={`flex items-center gap-1.5 mt-1 opacity-50 text-[8px] ${msg.isMe ? 'justify-end' : 'justify-start'}`}>
                    {msg.isEdited && <span className="font-black uppercase tracking-tighter">[Đã sửa]</span>}
                    <span>{msg.time}</span>
                  </div>
                  {msg.reaction && (
                    <button 
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        if (selectedChatId) onReactToMessage(selectedChatId, msg.id, msg.reaction!);
                      }}
                      className={`absolute -bottom-2 ${msg.isMe ? '-left-1' : '-right-1'} bg-white dark:bg-slate-700 shadow-md border border-brand-gold/30 rounded-full px-1.5 py-0.5 text-[10px] animate-in zoom-in-50 cursor-pointer active:scale-90 transition-transform`}
                    >
                      {msg.reaction}
                    </button>
                  )}
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>
        )}
      </main>

      {/* Message Input with Preview Area */}
      {selectedChat && (
        <div className="p-4 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-t border-brand-gold/20 safe-pb">
          {/* Reply Preview */}
          {replyingToMessage && (
            <div className="px-4 py-3 mb-3 bg-brand-cream dark:bg-slate-800 rounded-2xl flex items-center justify-between border-l-4 border-brand-gold shadow-sm animate-in slide-in-from-bottom-2">
              <div className="flex-1 overflow-hidden pr-4">
                <p className="text-[9px] font-black text-brand-red dark:text-brand-gold uppercase mb-1">
                  Đang trả lời <span className="italic">{replyingToMessage.isMe ? "chính mình" : selectedChat.userName}</span>
                </p>
                <p className="text-[10px] text-slate-500 dark:text-slate-400 truncate italic">"{replyingToMessage.text}"</p>
              </div>
              <button onClick={() => setReplyingToMessage(null)} className="w-6 h-6 rounded-full bg-brand-red/10 flex items-center justify-center text-brand-red">
                <i className="fa-solid fa-xmark text-xs"></i>
              </button>
            </div>
          )}

          {/* Edit Preview */}
          {editingMessageId && (
            <div className="px-4 py-2 mb-2 bg-brand-gold/10 rounded-xl flex items-center justify-between border border-brand-gold/20">
              <p className="text-[9px] font-black text-brand-red uppercase italic">Đang chỉnh sửa...</p>
              <button onClick={() => { setEditingMessageId(null); setInputValue(''); }} className="text-brand-red"><i className="fa-solid fa-xmark"></i></button>
            </div>
          )}

          <div className="flex items-center gap-3">
            <button className="text-brand-red dark:text-brand-gold"><i className="fa-solid fa-circle-plus text-xl"></i></button>
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Aa..."
                className="w-full bg-brand-cream dark:bg-slate-800 border border-brand-gold/30 rounded-full px-5 py-3 text-xs font-bold text-slate-800 dark:text-slate-200 outline-none focus:border-brand-red transition-all"
              />
            </div>
            <button 
              onClick={handleSend}
              className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${inputValue.trim() ? 'bg-brand-red text-brand-gold shadow-md scale-110' : 'text-slate-300'}`}
              disabled={!inputValue.trim()}
            >
              <i className={editingMessageId ? "fa-solid fa-check" : "fa-solid fa-paper-plane"}></i>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

