                <i className="fa-solid fa-xmark text-xs"></i>
              </button>
            </div>
          )}

          {editingMessageId && (
            <div className="px-4 py-2 mb-2 bg-brand-gold/10 rounded-xl flex items-center justify-between border border-brand-gold/20">
              <p className="text-[9px] font-black text-brand-red uppercase italic">Đang chỉnh sửa...</p>
              <button onClick={() => { setEditingMessageId(null); setInputValue(''); }} className="text-brand-red"><i className="fa-solid fa-xmark"></i></button>
            </div>
          )}

          <div className="flex items-center gap-3">
            <button className="text-brand-red dark:text-brand-gold"><i className="fa-solid fa-circle-plus text-xl"></i></button>
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Aa..."
                className="w-full bg-brand-cream dark:bg-slate-800 border border-brand-gold/30 rounded-full px-5 py-3 text-xs font-bold text-slate-800 dark:text-slate-200 outline-none focus:border-brand-red transition-all"
              />
            </div>
            <button 
              onClick={handleSend}
              className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${inputValue.trim() ? 'bg-brand-red text-brand-gold shadow-md scale-110' : 'text-slate-300'}`}
              disabled={!inputValue.trim()}
            >
              <i className={editingMessageId ? "fa-solid fa-check" : "fa-solid fa-paper-plane"}></i>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

