import React, { useState } from 'react';
import { Garment, TravelPlan } from '../types';
import { generateTravelPlan } from '../services/geminiService';
import { TravelSection } from './TravelSection';

interface OutfitResultProps {
  outfit: any;
  top: Garment;
  bottom: Garment;
}

const FALLBACK_IMAGE = 'https://images.unsplash.com/photo-1594932224828-b4b059b6f6ee?q=80&w=500&auto=format&fit=crop';

export const OutfitResult: React.FC<OutfitResultProps> = ({ outfit, top, bottom }) => {
  const [showCityInput, setShowCityInput] = useState(false);
  const [city, setCity] = useState('');
  const [isLoadingTravel, setIsLoadingTravel] = useState(false);
  const [travelPlan, setTravelPlan] = useState<{plan: TravelPlan, sources: any[]} | null>(null);

  const handleGetTravelPlan = async () => {
    if (!city.trim()) return;
    setIsLoadingTravel(true);
    try {
      const result = await generateTravelPlan(city, outfit.description, outfit.personality);
      if (result) {
        setTravelPlan(result);
        setShowCityInput(false);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoadingTravel(false);
    }
  };

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    e.currentTarget.src = FALLBACK_IMAGE;
  };

  return (
    <div className="space-y-6">
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl border border-brand-gold/20 animate-in fade-in slide-in-from-bottom-8 duration-700 transition-colors">
        {/* Visual Showcase - Side by Side */}
        <div className="p-5 bg-gradient-to-b from-brand-cream to-white dark:from-slate-950 dark:to-slate-900 flex gap-4 transition-colors">
          <div className="flex-1 aspect-[3/4] bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-brand-gold/10 dark:border-slate-700 p-3 flex items-center justify-center relative group transition-colors">
            <img 
              src={top?.image} 
              className="w-full h-full object-contain" 
              alt="Top" 
              onError={handleImageError}
            />
            <div className="absolute top-2 left-2 px-2 py-0.5 bg-brand-red text-white text-[9px] font-black rounded shadow uppercase border border-brand-gold/20 z-10">ÁO</div>
          </div>
          <div className="flex-1 aspect-[3/4] bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-brand-gold/10 dark:border-slate-700 p-3 flex items-center justify-center relative transition-colors">
            <img 
              src={bottom?.image} 
              className="w-full h-full object-contain" 
              alt="Bottom" 
              onError={handleImageError}
            />
            <div className="absolute top-2 left-2 px-2 py-0.5 bg-brand-red text-white text-[9px] font-black rounded shadow uppercase border border-brand-gold/20 z-10">QUẦN</div>
          </div>
        </div>

        {/* Dynamic Styling Info */}
        <div className="p-6 pt-2 space-y-6">
          <div className="space-y-1">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-[10px] font-black bg-brand-red text-brand-goldLight px-3 py-1 rounded-full uppercase tracking-widest border border-brand-gold/30">Match Score: 98%</span>
              <span className="text-[10px] font-black bg-brand-gold/20 text-brand-red px-3 py-1 rounded-full uppercase tracking-widest">Style: {outfit.personality.split(' ')[0]}</span>
            </div>
            <h3 className="text-2xl font-black text-brand-red dark:text-slate-100 leading-none tracking-tighter uppercase">{outfit.name}</h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 font-medium italic border-l-2 border-brand-gold pl-4 py-1 leading-relaxed">
              "{outfit.description}"
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div className="space-y-1">
                <p className="text-[9px] font-black text-brand-gold uppercase tracking-widest">Tính cách</p>
                <p className="text-xs text-brand-redLight dark:text-slate-300 font-bold leading-tight">{outfit.personality}</p>
             </div>
             <div className="space-y-2">
                <p className="text-[9px] font-black text-brand-gold uppercase tracking-widest">Bối cảnh</p>
                <div className="flex flex-wrap gap-1">
                  {outfit.locations.map((loc: string, i: number) => (
                    <span key={i} className="text-[8px] bg-brand-red/5 dark:bg-slate-800 text-brand-red dark:text-brand-gold px-2 py-0.5 rounded-lg font-black uppercase border border-brand-gold/10">{loc}</span>
                  ))}
                </div>
             </div>
          </div>

          {/* Travel Ecosystem Activation */}
          {!travelPlan && (
            <div className="pt-6 border-t border-brand-gold/10 dark:border-slate-800">
              {!showCityInput ? (
                <button 
                  onClick={() => setShowCityInput(true)}
                  className="w-full py-5 bg-brand-red text-white rounded-[1.5rem] font-black flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl border border-brand-gold/40"
                >
                  <i className="fa-solid fa-map-location-dot text-brand-gold"></i>
                  KHÁM PHÁ DU LỊCH CÙNG BỘ NÀY
                </button>
              ) : (
                <div className="space-y-4 animate-in fade-in zoom-in-95 duration-300">
                  <div className="space-y-1 px-1">
                    <p className="text-[10px] font-black text-brand-gold uppercase tracking-widest">Nhập thành phố dự định ghé thăm</p>
