                  <div className="flex gap-2">
                    <button 
                      onClick={handleGetTravelPlan}
                      disabled={isLoadingTravel || !city.trim()}
                      className="flex-1 py-4 bg-brand-red text-white rounded-2xl font-black active:scale-95 flex items-center justify-center gap-2 shadow-lg border border-brand-gold/30"
                    >
                      {isLoadingTravel ? <i className="fa-solid fa-circle-notch animate-spin"></i> : 'KHỞI HÀNH'}
                    </button>
                    <button 
                      onClick={() => setShowCityInput(false)}
                      className="w-14 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-2xl flex items-center justify-center active:bg-slate-200 transition-colors"
                    >
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {travelPlan && (
        <div className="pb-12">
          <TravelSection 
            plan={travelPlan.plan} 
            city={city} 
            sources={travelPlan.sources} 
          />
        </div>
      )}
    </div>
  );
};

