const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'generate' | 'profile'>('home');
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [tops, setTops] = useState<Garment[]>([]);
  const [bottoms, setBottoms] = useState<Garment[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GeminiOutfitResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatContextPost, setChatContextPost] = useState<Post | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  // State mới để lưu trữ Travel Plans cho từng outfit, tránh mất dữ liệu khi chuyển tab
  const [travelPlans, setTravelPlans] = useState<Record<number, {plan: TravelPlan, sources: any[], city: string}>>({});

  const [conversations, setConversations] = useState<ChatConversation[]>(INITIAL_CHATS);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const handleOpenChatFromPost = (post: Post) => {
    const existingChat = conversations.find(c => c.userName === post.user.name);
    if (existingChat) {
      setActiveChatId(existingChat.id);
    } else {
      setActiveChatId(conversations[0].id);
    }
    setChatContextPost(post);
    setIsChatOpen(true);
  };

  const handleSendMessage = (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        if (messageIdToEdit) {
          return {
            ...chat,
            messages: chat.messages.map(m => m.id === messageIdToEdit ? { ...m, text, isEdited: true } : m)
          };
        } else {
          const newMessage: Message = {
            id: Math.random().toString(36).substr(2, 9),
            text,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMe: true,
            replyTo
          };
          return {
            ...chat,
            lastMessage: text,
            messages: [...chat.messages, newMessage]
          };
        }
      }
      return chat;
    }));
  };

  const handleRecallMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => m.id === messageId ? { ...m, isRecalled: true, text: 'Tin nhắn đã được thu hồi' } : m)
        };
      }
      return chat;
    }));
  };

  const handleDeleteMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.filter(m => m.id !== messageId)
        };
      }
      return chat;
    }));
  };

  const handleReactToMessage = (chatId: string, messageId: string, reaction: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => {
            if (m.id === messageId) {
              return { ...m, reaction: m.reaction === reaction ? undefined : reaction };
            }
            return m;
          })
        };
      }
      return chat;
    }));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: GarmentType) => {
    const files = e.target.files;
    if (!files) return;
    setError(null);
    (Array.from(files) as File[]).forEach(file => {
      if (file.size > 5 * 1024 * 1024) {
        setError("Ảnh quá lớn! Vui lòng chọn ảnh dưới 5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const newGarment: Garment = {
          id: Math.random().toString(36).substr(2, 9),
          type,
          name: file.name,
          image: reader.result as string
        };
        if (type === GarmentType.TOP) {
          setTops(prev => [...prev, newGarment]);
        } else {
          setBottoms(prev => [...prev, newGarment]);
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const removeGarment = (id: string, type: GarmentType) => {
    if (type === GarmentType.TOP) {
      setTops(prev => prev.filter(g => g.id !== id));
    } else {
      setBottoms(prev => prev.filter(g => g.id !== id));
    }
  };

  const handleGenerate = async () => {
    if (tops.length === 0 || bottoms.length === 0) {
      setError("Vui lòng thêm ít nhất 1 ảnh áo và 1 ảnh quần.");
      return;
    }
    setIsGenerating(true);
    setError(null);
    try {
      const response = await generateOutfitsFromImages(tops, bottoms);
      if (response && response.outfits && response.outfits.length > 0) {
        setResult(response);
        setTravelPlans({}); // Reset travel plans when new outfits are generated
      } else {
        setError("AI không thể phân tích được ảnh. Hãy thử ảnh rõ nét hơn!");
      }
    } catch (err) {
      setError("Lỗi kết nối Server AI. Vui lòng thử lại sau!");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderHome = () => (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className="relative h-48 bg-brand-red dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-8 text-white shadow-xl border-b-4 border-brand-gold/50">
        <div className="relative z-10">
          <h2 className="text-2xl font-black mb-2 text-brand-goldLight">Chào Fashionista!</h2>
          <p className="text-xs text-white/90 max-w-[200px] leading-relaxed font-semibold">Khám phá phong cách thượng lưu của riêng bạn ngay hôm nay.</p>
        </div>
        <i className="fa-solid fa-sparkles absolute top-6 right-8 text-4xl text-brand-gold animate-pulse"></i>
        <div className="absolute -bottom-10 -right-10 opacity-10 rotate-12 text-brand-gold">
          <i className="fa-solid fa-shirt text-[150px]"></i>
        </div>
      </div>
      <section className="space-y-4">
        <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest px-1">Gợi ý phong cách</h3>
        <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x">
          {['Minimalism', 'Vintage', 'Streetwear', 'Chic'].map((style, i) => (
            <div key={i} className="flex-shrink-0 w-36 h-44 bg-white dark:bg-slate-900 rounded-[2rem] p-5 border border-brand-gold/20 dark:border-slate-800 flex flex-col justify-end shadow-sm snap-center">
              <span className="text-[10px] font-black text-brand-gold uppercase">Style</span>
              <p className="font-bold text-brand-red dark:text-slate-100">{style}</p>
            </div>
          ))}
        </div>
      </section>
      <section className="space-y-6">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Cộng đồng SmartStylist</h3>
          <button className="text-[10px] font-black text-brand-gold uppercase tracking-tighter">Xem thêm</button>
        </div>
        <div className="space-y-8">
          {MOCK_POSTS.map(post => (
            <SocialPost key={post.id} post={post} onTransactionClick={() => handleOpenChatFromPost(post)} />
          ))}
        </div>
      </section>
    </div>
  );

  const renderGenerate = () => (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-10">
      {!result ? (
        <>
          <section className="space-y-4">
            <div className="flex items-center justify-between px-1">
              <h3 className="font-black text-brand-red dark:text-slate-200 flex items-center gap-2 uppercase text-xs tracking-wider">
                <i className="fa-solid fa-shirt text-brand-gold"></i> Áo (Tops)
              </h3>
              <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full active:scale-95 transition-all cursor-pointer border border-brand-gold/30">
                + THÊM
                <input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.TOP)} />
              </label>
            </div>
            {tops.length === 0 ? (
              <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 dark:border-slate-800 rounded-[2.5rem] h-36 flex flex-col items-center justify-center text-slate-400 gap-2">
                <i className="fa-solid fa-camera text-2xl opacity-20 text-brand-red"></i>
                <p className="text-[9px] font-bold uppercase tracking-widest text-brand-red/40">Chưa có dữ liệu áo</p>
              </div>
            ) : (
              <div className="grid grid-cols-3 gap-3">
                {tops.map(g => (
                  <GarmentCard key={g.id} garment={g} onRemove={(id) => removeGarment(id, GarmentType.TOP)} />
                ))}
              </div>
            )}
          </section>
          <section className="space-y-4">
            <div className="flex items-center justify-between px-1">
              <h3 className="font-black text-brand-red dark:text-slate-200 flex items-center gap-2 uppercase text-xs tracking-wider">
                <i className="fa-solid fa-person-half-dress text-brand-gold"></i> Quần & Váy
              </h3>
              <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full active:scale-95 transition-all cursor-pointer border border-brand-gold/30">
                + THÊM
                <input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.BOTTOM)} />
              </label>
            </div>
            {bottoms.length === 0 ? (
