import React, { useState, useEffect } from 'react';
import { Garment, TravelPlan } from '../types';
import { generateTravelPlan } from '../services/geminiService';
import { TravelSection } from './TravelSection';

interface OutfitResultProps {
  outfit: any;
  top: Garment;
  bottom: Garment;
  savedTravelPlan?: { plan: TravelPlan, sources: any[], city: string };
  onTravelPlanGenerated: (data: { plan: TravelPlan, sources: any[], city: string }) => void;
}

const FALLBACK_IMAGE = 'https://images.unsplash.com/photo-1594932224828-b4b059b6f6ee?q=80&w=500&auto=format&fit=crop';

const LOADING_MESSAGES = [
  "Đang thiết lập hành trình thượng lưu...",
  "Tìm kiếm điểm đến đẳng cấp tại địa phương...",
  "Đang chọn lọc tinh hoa ẩm thực...",
  "Sắp xếp phương tiện di chuyển tối ưu...",
  "Hoàn thiện lịch trình dành riêng cho bạn..."
];

export const OutfitResult: React.FC<OutfitResultProps> = ({ 
  outfit, 
  top, 
  bottom, 
  savedTravelPlan,
  onTravelPlanGenerated
}) => {
  const [showCityInput, setShowCityInput] = useState(false);
  const [city, setCity] = useState(savedTravelPlan?.city || '');
  const [isLoadingTravel, setIsLoadingTravel] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);

  useEffect(() => {
    let interval: any;
    if (isLoadingTravel) {
      interval = setInterval(() => {
        setLoadingMsgIdx(prev => (prev + 1) % LOADING_MESSAGES.length);
      }, 2500);
    }
    return () => clearInterval(interval);
  }, [isLoadingTravel]);

  const handleGetTravelPlan = async () => {
    if (!city.trim()) return;
    setIsLoadingTravel(true);
    setLoadingMsgIdx(0);
    try {
      const result = await generateTravelPlan(city, outfit.description, outfit.personality);
      if (result) {
        onTravelPlanGenerated({
          plan: result.plan,
          sources: result.sources,
          city: city
        });
        setShowCityInput(false);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoadingTravel(false);
    }
  };

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    e.currentTarget.src = FALLBACK_IMAGE;
  };

  return (
    <div className="space-y-6">
      {/* RED LUXURY TRAVEL LOADING OVERLAY */}
      {isLoadingTravel && (
        <div className="fixed inset-0 bg-brand-red z-[200] flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500 overflow-hidden">
          {/* Background Decorative Icons */}
          <div className="absolute inset-0 opacity-[0.03] pointer-events-none flex flex-wrap gap-20 p-10 items-center justify-center">
             {[...Array(12)].map((_, i) => (
               <i key={i} className={`fa-solid ${i % 2 === 0 ? 'fa-shirt' : 'fa-plane'} text-[100px] -rotate-12`}></i>
             ))}
          </div>

          <div className="relative z-10 flex flex-col items-center">
            {/* Animated Compass Icon with Gold Border */}
            <div className="w-28 h-28 bg-white/5 rounded-[3rem] border-2 border-brand-gold flex items-center justify-center mb-12 shadow-[0_0_50px_rgba(212,175,55,0.4)] animate-in zoom-in duration-700">
              <div className="relative">
                <i className="fa-solid fa-compass text-5xl text-brand-gold animate-[spin_4s_linear_infinite]"></i>
                <div className="absolute inset-0 blur-md bg-brand-gold/30 animate-pulse"></div>
              </div>
            </div>

            <div className="space-y-5 max-w-xs">
              <h3 className="text-2xl font-black text-brand-goldLight uppercase tracking-[0.2em] italic drop-shadow-md">
                Đang Khởi Hành
              </h3>

              <div className="h-[2px] w-16 bg-brand-gold/50 mx-auto"></div>

              <p className="text-white/90 text-sm font-semibold h-12 flex items-center justify-center italic tracking-wide">
                {LOADING_MESSAGES[loadingMsgIdx]}
              </p>
            </div>

            {/* Premium Slim Progress Bar */}
            <div className="mt-16 w-56 h-[3px] bg-white/10 rounded-full overflow-hidden border border-white/5">
              <div className="h-full bg-brand-gold shadow-[0_0_10px_#D4AF37] animate-[loading_15s_ease-in-out_infinite]" style={{width: '100%'}}></div>
            </div>

            <p className="mt-8 text-[9px] font-black text-brand-gold/40 uppercase tracking-[0.4em]">SmartStylist Travel Ecosystem</p>
          </div>

          <style>{`
            @keyframes loading {
              0% { transform: translateX(-100%); }
              50% { transform: translateX(0%); }
              100% { transform: translateX(100%); }
            }
          `}</style>
        </div>
      )}

      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl border border-brand-gold/20 animate-in fade-in slide-in-from-bottom-8 duration-700 transition-colors">
        {/* Visual Showcase - Side by Side */}
        <div className="p-5 bg-gradient-to-b from-brand-cream to-white dark:from-slate-950 dark:to-slate-900 flex gap-4 transition-colors">
          <div className="flex-1 aspect-[3/4] bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-brand-gold/10 dark:border-slate-700 p-3 flex items-center justify-center relative group transition-colors">
            <img 
              src={top?.image} 
              className="w-full h-full object-contain" 
              alt="Top" 
              onError={handleImageError}
            />
            <div className="absolute top-2 left-2 px-2 py-0.5 bg-brand-red text-white text-[9px] font-black rounded shadow uppercase border border-brand-gold/20 z-10">ÁO</div>
          </div>
          <div className="flex-1 aspect-[3/4] bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-brand-gold/10 dark:border-slate-700 p-3 flex items-center justify-center relative transition-colors">
            <img 
              src={bottom?.image} 
              className="w-full h-full object-contain" 
              alt="Bottom" 
              onError={handleImageError}
            />
            <div className="absolute top-2 left-2 px-2 py-0.5 bg-brand-red text-white text-[9px] font-black rounded shadow uppercase border border-brand-gold/20 z-10">QUẦN</div>
          </div>
        </div>

        {/* Dynamic Styling Info */}
        <div className="p-6 pt-2 space-y-6">
          <div className="space-y-1">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-[10px] font-black bg-brand-red text-brand-goldLight px-3 py-1 rounded-full uppercase tracking-widest border border-brand-gold/30">Match Score: 98%</span>
              <span className="text-[10px] font-black bg-brand-gold/20 text-brand-red px-3 py-1 rounded-full uppercase tracking-widest italic">Style: {outfit.name}</span>
            </div>
            <h3 className="text-2xl font-black text-brand-red dark:text-slate-100 leading-none tracking-tighter uppercase">{outfit.name}</h3>
            <p className="text-sm text-slate-600 dark:text-slate-400 font-medium italic border-l-2 border-brand-gold pl-4 py-1 leading-relaxed">
              "{outfit.description}"
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div className="space-y-1">
                <p className="text-[9px] font-black text-brand-gold uppercase tracking-widest">Tính cách</p>
                <p className="text-xs text-brand-red dark:text-slate-300 font-bold leading-tight">{outfit.personality}</p>
             </div>
             <div className="space-y-2">
                <p className="text-[9px] font-black text-brand-gold uppercase tracking-widest">Bối cảnh</p>
                <div className="flex flex-wrap gap-1">
                  {outfit.locations.map((loc: string, i: number) => (
                    <span key={i} className="text-[8px] bg-brand-red/5 dark:bg-slate-800 text-brand-red dark:text-brand-gold px-2 py-0.5 rounded-lg font-black uppercase border border-brand-gold/10">{loc}</span>
                  ))}
                </div>
             </div>
          </div>

          {/* Travel Ecosystem Activation */}
          {!savedTravelPlan && (
            <div className="pt-6 border-t border-brand-gold/10 dark:border-slate-800">
              {!showCityInput ? (
                <button 
                  onClick={() => setShowCityInput(true)}
                  className="w-full py-5 bg-brand-red text-white rounded-[1.5rem] font-black flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl border border-brand-gold/40"
                >
                  <i className="fa-solid fa-map-location-dot text-brand-gold"></i>
                  KHÁM PHÁ DU LỊCH CÙNG BỘ NÀY
                </button>
              ) : (
                <div className="space-y-4 animate-in fade-in zoom-in-95 duration-300">
                  <div className="space-y-1 px-1">
                    <p className="text-[10px] font-black text-brand-gold uppercase tracking-widest">Nhập thành phố dự định ghé thăm</p>
                    <input 
                      type="text" 
                      value={city}
                      onChange={(e) => setCity(e.target.value)}
                      placeholder="Ví dụ: Hà Nội, Đà Lạt..."
                      className="w-full bg-brand-cream dark:bg-slate-800 border-2 border-brand-gold/20 rounded-2xl px-5 py-4 text-sm font-bold text-brand-red focus:border-brand-red outline-none transition-all shadow-inner"
                      autoFocus
                      onKeyDown={(e) => e.key === 'Enter' && handleGetTravelPlan()}
                    />
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={handleGetTravelPlan}
                      disabled={isLoadingTravel || !city.trim()}
                      className="flex-1 py-4 bg-brand-red text-white rounded-2xl font-black active:scale-95 flex items-center justify-center gap-2 shadow-lg border border-brand-gold/30 disabled:opacity-50"
                    >
                      KHỞI HÀNH
                    </button>
                    <button 
                      onClick={() => setShowCityInput(false)}
                      className="w-14 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-2xl flex items-center justify-center active:bg-slate-200 transition-colors"
                    >
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {savedTravelPlan && (
        <div className="pb-12">
          <TravelSection 
            plan={savedTravelPlan.plan} 
            city={savedTravelPlan.city} 
            sources={savedTravelPlan.sources} 
          />
        </div>
      )}
    </div>
  );
};

