              </p>
            </div>

            {/* Premium Slim Progress Bar */}
            <div className="mt-16 w-56 h-[3px] bg-white/10 rounded-full overflow-hidden border border-white/5">
              <div className="h-full bg-brand-gold shadow-[0_0_10px_#D4AF37] animate-[loading_15s_ease-in-out_infinite]" style={{width: '100%'}}></div>
            </div>

            <p className="mt-8 text-[9px] font-black text-brand-gold/40 uppercase tracking-[0.4em]">LuckyDream Travel Ecosystem</p>
          </div>

