    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [tops, setTops] = useState<Garment[]>([]);
  const [bottoms, setBottoms] = useState<Garment[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GeminiOutfitResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatContextPost, setChatContextPost] = useState<Post | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [travelPlans, setTravelPlans] = useState<Record<number, {plan: TravelPlan, sources: any[], city: string}>>({});
  const [conversations, setConversations] = useState<ChatConversation[]>(INITIAL_CHATS);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const handleOpenChatFromPost = (post: Post) => {
    const existingChat = conversations.find(c => c.userName === post.user.name);
    if (existingChat) {
      setActiveChatId(existingChat.id);
    } else {
      setActiveChatId(conversations[0].id);
    }
    setChatContextPost(post);
    setIsChatOpen(true);
  };

  const handleSendMessage = (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        if (messageIdToEdit) {
          return {
            ...chat,
            messages: chat.messages.map(m => m.id === messageIdToEdit ? { ...m, text, isEdited: true } : m)
          };
        } else {
          const newMessage: Message = {
            id: Math.random().toString(36).substr(2, 9),
            text,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMe: true,
            replyTo
          };
          return {
            ...chat,
            lastMessage: text,
            messages: [...chat.messages, newMessage]
          };
        }
      }
      return chat;
    }));
  };

  const handleRecallMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => m.id === messageId ? { ...m, isRecalled: true, text: 'Tin nhắn đã được thu hồi' } : m)
        };
      }
      return chat;
    }));
  };

  const handleDeleteMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.filter(m => m.id !== messageId)
        };
      }
      return chat;
    }));
  };

  const handleReactToMessage = (chatId: string, messageId: string, reaction: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => {
            if (m.id === messageId) {
              return { ...m, reaction: m.reaction === reaction ? undefined : reaction };
            }
            return m;
          })
        };
      }
      return chat;
    }));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: GarmentType) => {
    const files = e.target.files;
    if (!files) return;
    setError(null);
    (Array.from(files) as File[]).forEach(file => {
      if (file.size > 5 * 1024 * 1024) {
        setError("Ảnh quá lớn! Vui lòng chọn ảnh dưới 5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const newGarment: Garment = {
          id: Math.random().toString(36).substr(2, 9),
          type,
          name: file.name,
          image: reader.result as string
        };
        if (type === GarmentType.TOP) {
          setTops(prev => [...prev, newGarment]);
        } else {
          setBottoms(prev => [...prev, newGarment]);
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const removeGarment = (id: string, type: GarmentType) => {
    if (type === GarmentType.TOP) {
      setTops(prev => prev.filter(g => g.id !== id));
    } else {
      setBottoms(prev => prev.filter(g => g.id !== id));
    }
  };

