    if (tops.length === 0 || bottoms.length === 0) {
      setError("Vui lòng thêm ít nhất 1 ảnh áo và 1 ảnh quần.");
      return;
    }
    setIsGenerating(true);
    setError(null);
    try {
      const response = await generateOutfitsFromImages(tops, bottoms);
      if (response && response.outfits && response.outfits.length > 0) {
        setResult(response);
        setTravelPlans({});
      } else {
        setError("AI không thể phân tích được ảnh. Hãy thử ảnh rõ nét hơn!");
      }
    } catch (err) {
      setError("Lỗi kết nối Server AI. Vui lòng thử lại sau!");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex flex-col h-[100dvh] max-w-md mx-auto bg-brand-cream dark:bg-slate-950 relative shadow-2xl overflow-hidden font-sans transition-colors duration-300">
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center justify-between border-b-2 border-brand-gold/40 sticky top-0 z-30 transition-colors shadow-lg">
        <h1 className="text-2xl font-black text-brand-goldLight tracking-tighter uppercase italic drop-shadow-sm">LuckyDream</h1>
        <div className="flex items-center gap-2">
           <button onClick={() => { setChatContextPost(null); setIsChatOpen(true); }} className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight text-sm border border-brand-gold/40 shadow-inner active:scale-90 transition-transform">
              <i className="fa-solid fa-comment-dots"></i>
           </button>
           <div className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight text-sm border border-brand-gold/40 shadow-inner">
              <i className="fa-solid fa-bell"></i>
           </div>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden">
        {/* Home Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'home' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in fade-in duration-500 pb-10">
            <div className="relative h-48 bg-brand-red dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-8 text-white shadow-xl border-b-4 border-brand-gold/50">
              <div className="relative z-10">
                <h2 className="text-2xl font-black mb-2 text-brand-goldLight">Chào Fashionista!</h2>
                <p className="text-xs text-white/90 max-w-[200px] leading-relaxed font-semibold">Khám phá phong cách thượng lưu của riêng bạn ngay hôm nay.</p>
              </div>
              <i className="fa-solid fa-sparkles absolute top-6 right-8 text-4xl text-brand-gold animate-pulse"></i>
              <div className="absolute -bottom-10 -right-10 opacity-10 rotate-12 text-brand-gold">
                <i className="fa-solid fa-shirt text-[150px]"></i>
              </div>
            </div>
            <section className="space-y-4">
              <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest px-1">Gợi ý phong cách</h3>
              <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x">
