               <i key={i} className={`fa-solid ${i % 2 === 0 ? 'fa-shirt' : 'fa-plane'} text-[100px] -rotate-12`}></i>
             ))}
          </div>
          <div className="relative z-10 flex flex-col items-center">
            <div className="w-28 h-28 bg-white/5 dark:bg-brand-gold/5 rounded-[3rem] border-2 border-brand-gold flex items-center justify-center mb-12 shadow-[0_0_50px_rgba(212,175,55,0.4)] animate-in zoom-in duration-700">
              <div className="relative">
                <i className="fa-solid fa-compass text-5xl text-brand-gold animate-[spin_4s_linear_infinite]"></i>
              </div>
            </div>
            <div className="space-y-5">
              <h3 className="text-2xl font-black text-brand-goldLight dark:text-brand-gold uppercase tracking-[0.2em] italic">Đang Khởi Hành</h3>
              <p className="text-white/90 dark:text-slate-300 text-sm font-semibold">{LOADING_MESSAGES[loadingMsgIdx]}</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl border border-brand-gold/20 animate-in fade-in slide-in-from-bottom-8 duration-700 relative">
        {/* Post Button Floating */}
        <button 
          onClick={() => setIsPostModalOpen(true)}
          className="absolute top-6 right-6 z-20 w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center text-brand-red shadow-2xl border border-brand-gold/30 active:scale-90 transition-all group"
        >
          <i className="fa-solid fa-paper-plane group-hover:animate-bounce"></i>
          <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 translate-y-full text-[8px] font-black text-brand-red dark:text-brand-gold uppercase tracking-tighter opacity-0 group-hover:opacity-100 transition-opacity">Đăng bài</span>
        </button>

