                      placeholder="Ví dụ: Hà Nội, Đà Lạt..."
                      className="w-full bg-brand-cream dark:bg-slate-800 border-2 border-brand-gold/20 rounded-2xl px-5 py-4 text-sm font-bold text-brand-red focus:border-brand-red outline-none transition-all shadow-inner"
                      autoFocus
                      onKeyDown={(e) => e.key === 'Enter' && handleGetTravelPlan()}
                    />
                  </div>
                  <div className="flex gap-2">
                    <button 
                      onClick={handleGetTravelPlan}
                      disabled={isLoadingTravel || !city.trim()}
                      className="flex-1 py-4 bg-brand-red text-white rounded-2xl font-black active:scale-95 flex items-center justify-center gap-2 shadow-lg border border-brand-gold/30 disabled:opacity-50"
                    >
                      KHỞI HÀNH
                    </button>
                    <button onClick={() => setShowCityInput(false)} className="w-14 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-2xl flex items-center justify-center active:bg-slate-200 transition-colors">
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {savedTravelPlan && (
        <div className="pb-12">
          <TravelSection plan={savedTravelPlan.plan} city={savedTravelPlan.city} sources={savedTravelPlan.sources} />
        </div>
      )}

      {/* Post Modal */}
      <CreatePostModal 
        isOpen={isPostModalOpen}
        onClose={() => setIsPostModalOpen(false)}
        topImage={top.image}
        bottomImage={bottom.image}
        suggestedLocations={allSuggestedLocations}
        onPublish={(data) => onPostPublished({ ...data, topImage: top.image, bottomImage: bottom.image })}
      />
    </div>
  );
};

