          </div>
          <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center justify-center gap-1 ${activeTab === 'profile' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>
            <i className="fa-solid fa-user-large text-xl"></i><span className="text-[9px] font-black uppercase">Tôi</span>
          </button>
        </div>
      </nav>

      {isGenerating && <div className="fixed inset-0 bg-brand-red/95 dark:bg-slate-950/95 backdrop-blur-md z-[300] flex flex-col items-center justify-center animate-in fade-in"><div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center mb-10 animate-bounce border-4 border-brand-gold"><i className="fa-solid fa-wand-magic-sparkles text-4xl text-brand-red"></i></div><h3 className="text-2xl font-black text-white uppercase tracking-tighter">Đang thiết kế...</h3></div>}
    </div>
  );
};

