            </section>
          </div>
        </div>
      </main>

      <ChatPanel isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} conversations={conversations} initialChatId={activeChatId} contextPost={chatContextPost} onSendMessage={handleSendMessage} onRecallMessage={()=>{}} onDeleteMessage={()=>{}} onReactToMessage={()=>{}} />

