        <div className="grid grid-cols-3 items-center h-20 px-4">
          <button onClick={() => setActiveTab('home')} className={`flex flex-col items-center justify-center gap-1 active:scale-90 transition-all ${activeTab === 'home' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>
            <i className={`fa-solid fa-house-chimney text-xl ${activeTab === 'home' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">Trang chủ</span>
          </button>
          <div className="relative flex justify-center">
            <button onClick={() => setActiveTab('generate')} className={`w-14 h-14 bg-brand-red rounded-full flex items-center justify-center shadow-xl border-4 border-brand-gold/50 absolute -top-12 transition-all active:scale-95 ${activeTab === 'generate' ? 'scale-110' : ''}`}>
              <i className="fa-solid fa-wand-magic-sparkles text-brand-gold text-xl"></i>
            </button>
            <span className={`text-[9px] font-black uppercase tracking-tighter mt-8 ${activeTab === 'generate' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>Phối đồ</span>
          </div>
          <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center justify-center gap-1 active:scale-90 transition-all ${activeTab === 'profile' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>
            <i className={`fa-solid fa-user-large text-xl ${activeTab === 'profile' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">Tôi</span>
          </button>
        </div>
      </nav>

      {isGenerating && <div className="fixed inset-0 bg-brand-red/95 dark:bg-slate-950/95 backdrop-blur-md z-[300] flex flex-col items-center justify-center animate-in fade-in transition-colors"><div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center mb-10 animate-bounce border-4 border-brand-gold"><i className="fa-solid fa-wand-magic-sparkles text-4xl text-brand-red"></i></div><h3 className="text-2xl font-black text-white uppercase tracking-tighter">Đang thiết kế...</h3><p className="text-brand-goldLight text-xs animate-pulse">Sáng tạo phong cách dành riêng cho bạn</p></div>}
    </div>
  );
};

export default App;

