    location: '📍 Hồ Xuân Hương – Đà Lạt',
    tags: ['Streetwear', 'DalatTrip', 'WinterVibe', 'OOTD'],
    transactionType: 'Thuê',
    stats: { likes: 89, comments: 5 },
