                  <OutfitResult 
                    key={idx} 
                    outfit={outfit} 
                    top={tops[outfit.topIndex]} 
                    bottom={bottoms[outfit.bottomIndex]} 
                    savedTravelPlan={travelPlans[idx]}
                    onTravelPlanGenerated={(data) => setTravelPlans(prev => ({...prev, [idx]: data}))}
