        <h1 className="text-2xl font-black text-brand-goldLight tracking-tighter uppercase italic">LuckyDream</h1>
        <div className="flex items-center gap-2">
           <button onClick={() => { setChatContextPost(null); setIsChatOpen(true); }} className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight border border-brand-gold/40 shadow-inner"><i className="fa-solid fa-comment-dots"></i></button>
           <div className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight border border-brand-gold/40 shadow-inner"><i className="fa-solid fa-bell"></i></div>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden">
        {/* Home Tab */}
        <div className={`absolute inset-0 overflow-y-auto smooth-scroll scrollbar-hide ${activeTab === 'home' ? 'block' : 'hidden'}`}>
          <div className="space-y-6 animate-in fade-in duration-500 pb-24">
            {/* Hero Banner Updated to match Image */}
            <div className="px-6 pt-6">
              <div className="relative h-48 bg-brand-red dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-8 text-white shadow-xl border-b-4 border-brand-gold/50 flex flex-col justify-center">
                {/* Single Subtle Ghost Silhouette */}
                <div className="absolute inset-0 z-0 opacity-5 pointer-events-none overflow-hidden">
                  <i className="fa-solid fa-shirt absolute -right-4 -bottom-10 text-[240px] text-white blur-[2px] rotate-[-5deg]"></i>
                </div>

                <div className="relative z-10 space-y-3">
                  <h2 className="text-[28px] font-black text-brand-goldLight drop-shadow-md tracking-tight leading-none">Chào Fashionista!</h2>
                  <p className="text-[13px] text-white/95 max-w-[240px] leading-tight font-bold">Khám phá phong cách thượng lưu của riêng bạn ngay hôm nay.</p>
                </div>
              </div>
            </div>

            {/* Style Categories Slidebar */}
            <div className="space-y-3">
              <div className="flex items-center justify-between px-7">
                <h3 className="text-[10px] font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Khám phá phong cách</h3>
                <span className="text-[9px] font-bold text-brand-gold uppercase">Xem thêm</span>
              </div>
              <div className="flex overflow-x-auto gap-4 px-6 pb-2 scrollbar-hide">
                {STYLE_CATEGORIES.map((cat) => (
                  <div key={cat.id} className="flex-shrink-0 flex flex-col items-center gap-2 group cursor-pointer">
                    <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-3xl border border-brand-gold/20 dark:border-slate-800 flex items-center justify-center text-brand-red dark:text-brand-gold shadow-sm group-active:scale-90 transition-all">
                      <i className={`fa-solid ${cat.icon} text-xl`}></i>
                    </div>
                    <span className="text-[9px] font-black uppercase text-slate-500 dark:text-slate-400 tracking-tighter">{cat.name}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Social Feed */}
            <section className="space-y-6 px-6 pt-2">
              <div className="flex items-center justify-between px-1">
                <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Cộng đồng LuckyDream</h3>
                <div className="flex gap-2">
                   <div className="w-8 h-8 bg-brand-cream dark:bg-slate-800 rounded-xl flex items-center justify-center text-brand-red text-xs border border-brand-gold/20 shadow-sm"><i className="fa-solid fa-filter"></i></div>
                </div>
              </div>
              <div className="space-y-4">
                {posts.map(post => (
                  <SocialPost 
                    key={post.id} 
                    post={post} 
                    onTransactionClick={() => handleOpenChatFromPost(post)} 
                  />
                ))}
              </div>
            </section>
          </div>
        </div>

        {/* Generate Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'generate' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-10">
            {!result ? (
              <>
                <section className="space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="font-black text-brand-red dark:text-slate-200 uppercase text-xs tracking-wider">Áo (Tops)</h3>
                    <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full cursor-pointer border border-brand-gold/30">+ THÊM<input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.TOP)} /></label>
                  </div>
                  {tops.length === 0 ? (
                    <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 rounded-[2rem] h-32 flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">Chưa có ảnh áo</div>
                  ) : (
                    <div className="grid grid-cols-3 gap-3">{tops.map(g => <GarmentCard key={g.id} garment={g} onRemove={() => setTops(tops.filter(i => i.id !== g.id))} />)}</div>
                  )}
                </section>
                <section className="space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="font-black text-brand-red dark:text-slate-200 uppercase text-xs tracking-wider">Quần & Váy</h3>
                    <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full cursor-pointer border border-brand-gold/30">+ THÊM<input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.BOTTOM)} /></label>
                  </div>
                  {bottoms.length === 0 ? (
                    <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 rounded-[2rem] h-32 flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">Chưa có ảnh quần</div>
                  ) : (
                    <div className="grid grid-cols-3 gap-3">{bottoms.map(g => <GarmentCard key={g.id} garment={g} onRemove={() => setBottoms(bottoms.filter(i => i.id !== g.id))} />)}</div>
                  )}
                </section>
                <button onClick={handleGenerate} disabled={isGenerating || tops.length === 0} className="w-full h-16 bg-brand-red text-brand-goldLight rounded-[1.5rem] font-black shadow-2xl flex items-center justify-center gap-3 border-2 border-brand-gold/40 active:scale-95 transition-all">
                  {isGenerating ? <i className="fa-solid fa-circle-notch animate-spin"></i> : "PHỐI ĐỒ NGAY"}
                </button>
              </>
            ) : (
              <div className="space-y-12 pb-10">
                <div className="flex items-center justify-between px-1">
                   <h3 className="text-xl font-black text-brand-red dark:text-slate-100">Gợi ý phong cách</h3>
                   <button onClick={() => { setResult(null); setTravelPlans({}); }} className="text-[10px] font-black text-white bg-brand-red px-4 py-2 rounded-full border border-brand-gold/30">Làm lại</button>
                </div>
                {result.outfits.map((outfit, idx) => (
                  <OutfitResult 
                    key={idx} 
                    outfit={outfit} 
                    top={tops[outfit.topIndex]} 
                    bottom={bottoms[outfit.bottomIndex]} 
                    savedTravelPlan={travelPlans[idx]}
                    onTravelPlanGenerated={(data) => setTravelPlans(prev => ({...prev, [idx]: data}))}
                    onPostPublished={handlePublishPost}
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Profile Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'profile' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in slide-in-from-left-4 duration-500 pb-10">
            <div className="flex flex-col items-center py-8 space-y-4">
              <div className="w-24 h-24 bg-brand-red rounded-[2.5rem] flex items-center justify-center text-3xl text-brand-gold border-4 border-brand-gold/30 shadow-2xl"><i className="fa-solid fa-user-ninja"></i></div>
              <div className="text-center">
                <h2 className="text-xl font-black text-brand-red dark:text-slate-100 uppercase tracking-tight">Fashionista VN</h2>
                <p className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.2em] bg-brand-red px-3 py-1 rounded-full inline-block mt-2">Level 1 Discoverer</p>
              </div>
            </div>

            <div className="space-y-3 px-1">
              <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between shadow-sm transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-brand-red/10 dark:bg-indigo-900/30 rounded-xl flex items-center justify-center text-brand-red">
                    <i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i>
