              <div className="flex items-center justify-between px-2">
                <h3 className="text-xs font-black text-brand-red dark:text-brand-gold uppercase tracking-[0.2em]">Lịch sử bài đăng</h3>
                <span className="text-[10px] text-slate-400 font-bold">{posts.filter(p => p.user.name === 'Fashionista VN').length} bài đăng</span>
              </div>
              <div className="space-y-8">
                {posts.filter(p => p.user.name === 'Fashionista VN').length === 0 ? (
                  <div className="p-10 text-center bg-white dark:bg-slate-900 rounded-[2.5rem] border border-dashed border-brand-gold/20">
                    <p className="text-[10px] font-black text-slate-400 uppercase italic">Bạn chưa có bài đăng nào.</p>
                  </div>
                ) : (
                  posts.filter(p => p.user.name === 'Fashionista VN').map(post => (
                    <SocialPost key={post.id} post={post} />
                  ))
                )}
              </div>
            </section>
          </div>
        </div>
      </main>

      <ChatPanel 
        isOpen={isChatOpen} 
        onClose={() => setIsChatOpen(false)} 
        conversations={conversations} 
        initialChatId={activeChatId} 
        contextPost={chatContextPost} 
        onSendMessage={handleSendMessage} 
        onRecallMessage={()=>{}} 
        onDeleteMessage={()=>{}} 
        onReactToMessage={()=>{}} 
      />

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/95 dark:bg-slate-900/95 backdrop-blur-2xl border-t border-brand-gold/30 z-40 safe-pb shadow-lg">
