const INITIAL_CHATS: ChatConversation[] = [
  {
    id: 'c1',
    userName: 'Thanh Hằng',
    userLevel: 'Elite Fashionista',
    avatar: 'TH',
    lastMessage: 'Áo đó còn size S không bạn nhỉ?',
    messages: [
      { id: 'm1', text: 'Chào Hằng, mình thấy bạn đăng thanh lý set đồ công sở.', time: '10:00', isMe: true },
      { id: 'm3', text: 'Áo đó còn size S không bạn nhỉ?', time: '10:05', isMe: false },
    ]
  }
];

const STYLE_CATEGORIES = [
  { id: 's1', name: 'Thượng lưu', icon: 'fa-crown' },
  { id: 's2', name: 'Tối giản', icon: 'fa-leaf' },
  { id: 's3', name: 'Đường phố', icon: 'fa-bolt' },
  { id: 's4', name: 'Công sở', icon: 'fa-briefcase' },
  { id: 's5', name: 'Hẹn hò', icon: 'fa-heart' },
  { id: 's6', name: 'Cổ điển', icon: 'fa-camera' }
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'generate' | 'profile'>('home');
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [tops, setTops] = useState<Garment[]>([]);
  const [bottoms, setBottoms] = useState<Garment[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GeminiOutfitResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatContextPost, setChatContextPost] = useState<Post | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [travelPlans, setTravelPlans] = useState<Record<number, {plan: TravelPlan, sources: any[], city: string}>>({});
  const [conversations, setConversations] = useState<ChatConversation[]>(INITIAL_CHATS);
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const handleOpenChatFromPost = (post: Post) => {
    let existingChat = conversations.find(c => c.userName === post.user.name);

    if (!existingChat) {
      const newChat: ChatConversation = {
        id: `chat-${post.user.name}-${Date.now()}`,
        userName: post.user.name,
        userLevel: post.user.level,
        avatar: post.user.avatar,
        lastMessage: `Xin chào! Mình muốn hỏi về bài đăng ${post.transactionType?.toLowerCase()} của bạn.`,
        messages: [
          { id: 'sys-1', text: `Bạn đang bắt đầu cuộc hội thoại về bài đăng của ${post.user.name}.`, time: 'Bây giờ', isMe: false }
        ]
      };
      setConversations(prev => [...prev, newChat]);
      setActiveChatId(newChat.id);
    } else {
      setActiveChatId(existingChat.id);
    }

    setChatContextPost(post);
    setIsChatOpen(true);
  };

  const handleSendMessage = (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        if (messageIdToEdit) {
          return { ...chat, messages: chat.messages.map(m => m.id === messageIdToEdit ? { ...m, text, isEdited: true } : m) };
        } else {
          const newMessage: Message = { id: Math.random().toString(36).substr(2, 9), text, time: 'Vừa xong', isMe: true, replyTo };
          return { ...chat, lastMessage: text, messages: [...chat.messages, newMessage] };
        }
      }
      return chat;
    }));
  };

  const handlePublishPost = (postData: Partial<Post>) => {
    const newPost: Post = {
      id: `user-${Date.now()}`,
      user: { name: 'Fashionista VN', avatar: 'Me', level: 'Level 1 Discoverer' },
      time: 'Vừa xong',
      description: postData.description || '',
      topImage: postData.topImage || '',
      bottomImage: postData.bottomImage || '',
      location: postData.location || 'LuckyDream Secret',
      tags: postData.tags || [],
      transactionType: postData.transactionType,
      stats: { likes: 0, comments: 0 },
      sampleComments: []
    };
    setPosts(prev => [newPost, ...prev]);
    setActiveTab('home'); 
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: GarmentType) => {
    const files = e.target.files;
    if (!files) return;
    (Array.from(files) as File[]).forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newGarment: Garment = { id: Math.random().toString(36).substr(2, 9), type, name: file.name, image: reader.result as string };
        if (type === GarmentType.TOP) setTops(prev => [...prev, newGarment]);
        else setBottoms(prev => [...prev, newGarment]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleGenerate = async () => {
    if (tops.length === 0 || bottoms.length === 0) return;
    setIsGenerating(true);
    try {
      const response = await generateOutfitsFromImages(tops, bottoms);
      if (response) {
        setResult(response);
        setTravelPlans({});
      }
    } catch (err) { setError("Lỗi kết nối."); }
    finally { setIsGenerating(false); }
  };

  return (
    <div className="flex flex-col h-[100dvh] max-w-md mx-auto bg-brand-cream dark:bg-slate-950 relative shadow-2xl overflow-hidden font-sans transition-colors duration-300">
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center justify-between border-b-2 border-brand-gold/40 sticky top-0 z-30 shadow-lg">
        <h1 className="text-2xl font-black text-brand-goldLight tracking-tighter uppercase italic">LuckyDream</h1>
        <div className="flex items-center gap-2">
           <button onClick={() => { setChatContextPost(null); setIsChatOpen(true); }} className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight border border-brand-gold/40 shadow-inner"><i className="fa-solid fa-comment-dots"></i></button>
           <div className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight border border-brand-gold/40 shadow-inner"><i className="fa-solid fa-bell"></i></div>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden">
        {/* Home Tab */}
        <div className={`absolute inset-0 overflow-y-auto smooth-scroll scrollbar-hide ${activeTab === 'home' ? 'block' : 'hidden'}`}>
          <div className="space-y-6 animate-in fade-in duration-500 pb-24">
            {/* Hero Banner Refined */}
            <div className="px-6 pt-6">
              <div className="relative h-48 bg-brand-red dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-8 text-white shadow-xl border-b-4 border-brand-gold/50 flex flex-col justify-center transition-all duration-500">
                {/* Subtle Ghost Silhouette: Bottom-Left, Tilted Right, Sharp in Light Mode */}
                <div className="absolute inset-0 z-0 pointer-events-none overflow-hidden">
                  <i className="fa-solid fa-shirt absolute -left-10 -bottom-10 text-[180px] text-white opacity-[0.12] dark:opacity-[0.04] rotate-[18deg]"></i>
                </div>

                <div className="relative z-10 space-y-3">
                  <h2 className="text-[28px] font-black text-brand-goldLight drop-shadow-md tracking-tight leading-none">Chào Fashionista!</h2>
                  <p className="text-[13px] text-white/95 max-w-[240px] leading-tight font-bold">Khám phá phong cách thượng lưu của riêng bạn ngay hôm nay.</p>
                </div>
              </div>
            </div>

            {/* Style Categories Slidebar */}
            <div className="space-y-3">
              <div className="flex items-center justify-between px-7">
                <h3 className="text-[10px] font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Khám phá phong cách</h3>
                <span className="text-[9px] font-bold text-brand-gold uppercase">Xem thêm</span>
              </div>
              <div className="flex overflow-x-auto gap-4 px-6 pb-2 scrollbar-hide">
                {STYLE_CATEGORIES.map((cat) => (
                  <div key={cat.id} className="flex-shrink-0 flex flex-col items-center gap-2 group cursor-pointer">
                    <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-3xl border border-brand-gold/20 dark:border-slate-800 flex items-center justify-center text-brand-red dark:text-brand-gold shadow-sm group-active:scale-90 transition-all">
                      <i className={`fa-solid ${cat.icon} text-xl`}></i>
                    </div>
                    <span className="text-[9px] font-black uppercase text-slate-500 dark:text-slate-400 tracking-tighter">{cat.name}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* Social Feed */}
            <section className="space-y-6 px-6 pt-2">
              <div className="flex items-center justify-between px-1">
                <h3 className="text-sm font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Cộng đồng LuckyDream</h3>
                <div className="flex gap-2">
                   <div className="w-8 h-8 bg-brand-cream dark:bg-slate-800 rounded-xl flex items-center justify-center text-brand-red text-xs border border-brand-gold/20 shadow-sm"><i className="fa-solid fa-filter"></i></div>
                </div>
              </div>
              <div className="space-y-4">
                {posts.map(post => (
                  <SocialPost 
                    key={post.id} 
                    post={post} 
                    onTransactionClick={() => handleOpenChatFromPost(post)} 
                  />
                ))}
              </div>
            </section>
          </div>
        </div>

        {/* Generate Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'generate' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-10">
            {!result ? (
              <>
                <section className="space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="font-black text-brand-red dark:text-slate-200 uppercase text-xs tracking-wider">Áo (Tops)</h3>
                    <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full cursor-pointer border border-brand-gold/30">+ THÊM<input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.TOP)} /></label>
                  </div>
                  {tops.length === 0 ? (
                    <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 rounded-[2rem] h-32 flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">Chưa có ảnh áo</div>
                  ) : (
                    <div className="grid grid-cols-3 gap-3">{tops.map(g => <GarmentCard key={g.id} garment={g} onRemove={() => setTops(tops.filter(i => i.id !== g.id))} />)}</div>
                  )}
                </section>
                <section className="space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="font-black text-brand-red dark:text-slate-200 uppercase text-xs tracking-wider">Quần & Váy</h3>
                    <label className="text-brand-goldLight bg-brand-red text-[10px] font-black px-4 py-2 rounded-full cursor-pointer border border-brand-gold/30">+ THÊM<input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.BOTTOM)} /></label>
                  </div>
                  {bottoms.length === 0 ? (
                    <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 rounded-[2rem] h-32 flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">Chưa có ảnh quần</div>
                  ) : (
                    <div className="grid grid-cols-3 gap-3">{bottoms.map(g => <GarmentCard key={g.id} garment={g} onRemove={() => setBottoms(bottoms.filter(i => i.id !== g.id))} />)}</div>
                  )}
                </section>
                <button onClick={handleGenerate} disabled={isGenerating || tops.length === 0} className="w-full h-16 bg-brand-red text-brand-goldLight rounded-[1.5rem] font-black shadow-2xl flex items-center justify-center gap-3 border-2 border-brand-gold/40 active:scale-95 transition-all">
                  {isGenerating ? <i className="fa-solid fa-circle-notch animate-spin"></i> : "PHỐI ĐỒ NGAY"}
                </button>
              </>
            ) : (
              <div className="space-y-12 pb-10">
                <div className="flex items-center justify-between px-1">
                   <h3 className="text-xl font-black text-brand-red dark:text-slate-100">Gợi ý phong cách</h3>
                   <button onClick={() => { setResult(null); setTravelPlans({}); }} className="text-[10px] font-black text-white bg-brand-red px-4 py-2 rounded-full border border-brand-gold/30">Làm lại</button>
                </div>
                {result.outfits.map((outfit, idx) => (
                  <OutfitResult 
                    key={idx} 
                    outfit={outfit} 
                    top={tops[outfit.topIndex]} 
                    bottom={bottoms[outfit.bottomIndex]} 
                    savedTravelPlan={travelPlans[idx]}
                    onTravelPlanGenerated={(data) => setTravelPlans(prev => ({...prev, [idx]: data}))}
                    onPostPublished={handlePublishPost}
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Profile Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'profile' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in slide-in-from-left-4 duration-500 pb-10">
            <div className="flex flex-col items-center py-8 space-y-4">
              <div className="w-24 h-24 bg-brand-red rounded-[2.5rem] flex items-center justify-center text-3xl text-brand-gold border-4 border-brand-gold/30 shadow-2xl"><i className="fa-solid fa-user-ninja"></i></div>
              <div className="text-center">
                <h2 className="text-xl font-black text-brand-red dark:text-slate-100 uppercase tracking-tight">Fashionista VN</h2>
                <p className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.2em] bg-brand-red px-3 py-1 rounded-full inline-block mt-2">Level 1 Discoverer</p>
              </div>
            </div>

            <div className="space-y-3 px-1">
              <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between shadow-sm transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-brand-red/10 dark:bg-indigo-900/30 rounded-xl flex items-center justify-center text-brand-red">
                    <i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i>
                  </div>
                  <span className="font-bold text-brand-red dark:text-slate-200">Giao diện tối</span>
                </div>
                <button 
                  onClick={() => setIsDarkMode(!isDarkMode)}
                  className={`w-12 h-6 rounded-full transition-all relative ${isDarkMode ? 'bg-brand-red' : 'bg-slate-300'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isDarkMode ? 'left-7' : 'left-1'}`}></div>
                </button>
              </div>

              {[
                { label: 'Địa điểm đã lưu', icon: 'fa-bookmark' },
                { label: 'Cài đặt tài khoản', icon: 'fa-gear' },
                { label: 'Trợ giúp & Phản hồi', icon: 'fa-circle-question' }
              ].map((item, i) => (
                <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-brand-cream dark:bg-slate-800 rounded-xl flex items-center justify-center text-brand-gold shadow-inner">
                      <i className={`fa-solid ${item.icon}`}></i>
                    </div>
                    <span className="font-bold text-brand-red dark:text-slate-200">{item.label}</span>
                  </div>
                  <i className="fa-solid fa-chevron-right text-[10px] text-brand-gold/70"></i>
                </div>
              ))}
            </div>

            <section className="space-y-6 pt-4">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-xs font-black text-brand-red dark:text-brand-gold uppercase tracking-[0.2em]">Lịch sử bài đăng</h3>
                <span className="text-[10px] text-slate-400 font-bold">{posts.filter(p => p.user.name === 'Fashionista VN').length} bài đăng</span>
              </div>
              <div className="space-y-8">
                {posts.filter(p => p.user.name === 'Fashionista VN').length === 0 ? (
                  <div className="p-10 text-center bg-white dark:bg-slate-900 rounded-[2.5rem] border border-dashed border-brand-gold/20">
                    <p className="text-[10px] font-black text-slate-400 uppercase italic">Bạn chưa có bài đăng nào.</p>
                  </div>
                ) : (
                  posts.filter(p => p.user.name === 'Fashionista VN').map(post => (
                    <SocialPost key={post.id} post={post} />
                  ))
                )}
              </div>
            </section>
          </div>
        </div>
      </main>

      <ChatPanel 
        isOpen={isChatOpen} 
        onClose={() => setIsChatOpen(false)} 
        conversations={conversations} 
        initialChatId={activeChatId} 
        contextPost={chatContextPost} 
        onSendMessage={handleSendMessage} 
        onRecallMessage={()=>{}} 
        onDeleteMessage={()=>{}} 
        onReactToMessage={()=>{}} 
      />

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/95 dark:bg-slate-900/95 backdrop-blur-2xl border-t border-brand-gold/30 z-40 safe-pb shadow-lg">
        <div className="grid grid-cols-3 items-center h-20 px-4">
          <button onClick={() => setActiveTab('home')} className={`flex flex-col items-center justify-center gap-1 active:scale-90 transition-all ${activeTab === 'home' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>
            <i className={`fa-solid fa-house-chimney text-xl ${activeTab === 'home' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase">Trang chủ</span>
          </button>
          <div className="relative flex justify-center">
            <button onClick={() => setActiveTab('generate')} className={`w-14 h-14 bg-brand-red rounded-full flex items-center justify-center shadow-xl border-4 border-brand-gold/50 absolute -top-12 transition-all active:scale-95 ${activeTab === 'generate' ? 'scale-110' : ''}`}>
              <i className="fa-solid fa-wand-magic-sparkles text-brand-gold text-xl"></i>
            </button>
            <span className={`text-[9px] font-black uppercase mt-8 ${activeTab === 'generate' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>Phối đồ</span>
          </div>
          <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center justify-center gap-1 active:scale-90 transition-all ${activeTab === 'profile' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>
            <i className={`fa-solid fa-user-large text-xl ${activeTab === 'profile' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase">Tôi</span>
          </button>
        </div>
      </nav>

      {isGenerating && <div className="fixed inset-0 bg-brand-red/95 dark:bg-slate-950/95 backdrop-blur-md z-[300] flex flex-col items-center justify-center animate-in fade-in transition-colors"><div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center mb-10 animate-bounce border-4 border-brand-gold"><i className="fa-solid fa-wand-magic-sparkles text-4xl text-brand-red"></i></div><h3 className="text-2xl font-black text-white uppercase tracking-tighter">Đang thiết kế...</h3></div>}
    </div>
  );
};

