                    <span className="text-[8px] text-slate-400">{chat.messages.length > 0 ? chat.messages[chat.messages.length - 1].time : ''}</span>
                  </div>
                  <p className="text-[10px] text-slate-500 dark:text-slate-400 truncate font-medium">{chat.lastMessage}</p>
                </div>
              </button>
            ))}
          </div>
        ) : (
          <>
            {contextPost && contextPost.user.name === selectedChat.userName && (
              <div className="sticky top-0 z-40 bg-brand-cream/90 dark:bg-slate-950/90 backdrop-blur-md px-4 py-3 border-b border-brand-gold/20 shadow-sm">
                <div className="bg-white dark:bg-slate-900 rounded-[1.5rem] border border-brand-gold/30 shadow-lg overflow-hidden flex flex-row items-center h-20">
                  <div className="flex gap-0.5 h-full p-1.5 bg-brand-cream dark:bg-slate-800">
                    <img src={contextPost.topImage} className="w-10 h-full object-cover rounded-lg" alt="Top" />
                    <img src={contextPost.bottomImage} className="w-10 h-full object-cover rounded-lg" alt="Bottom" />
                  </div>
                  <div className="flex-1 px-3 min-w-0">
                    <p className="text-[8px] font-black text-brand-gold uppercase mb-0.5">Đang thảo luận</p>
                    <p className="text-[10px] font-bold text-slate-800 dark:text-slate-100 truncate italic">"{contextPost.description.substring(0, 40)}..."</p>
                  </div>
                  <button className="h-full px-4 bg-brand-red text-brand-goldLight text-[9px] font-black uppercase min-w-[80px]">
                    {contextPost.transactionType === 'Thanh lý' ? 'MUA NGAY' : 'THUÊ NGAY'}
                  </button>
                </div>
              </div>
            )}

            <div className="flex flex-col gap-4 p-4 pb-20">
              <div className="text-center py-6">
                <div className="w-16 h-16 bg-brand-red rounded-[1.5rem] flex items-center justify-center text-brand-gold text-2xl font-black border-2 border-brand-gold/30 mx-auto shadow-xl mb-3">{selectedChat.avatar}</div>
                <p className="text-[10px] font-black text-brand-gold uppercase tracking-widest">{selectedChat.userLevel}</p>
              </div>

              {selectedChat.messages.map(msg => (
                <div 
                  key={msg.id} 
                  className={`flex flex-col ${msg.isMe ? 'items-end' : 'items-start'} select-none`}
                  onMouseDown={(e) => handleStartPress(e, msg)}
                  onMouseUp={handleEndPress}
                  onMouseLeave={handleEndPress}
                  onTouchStart={(e) => handleStartPress(e, msg)}
                  onTouchEnd={handleEndPress}
                >
                  <div className={`relative max-w-[80%] p-4 rounded-[2rem] shadow-sm text-xs font-semibold transition-all ${
                    msg.isRecalled 
                      ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 italic border border-slate-200 opacity-60'
                      : msg.isMe 
                        ? 'bg-brand-red text-brand-goldLight rounded-tr-none border border-brand-gold/20' 
                        : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-tl-none border border-brand-gold/10'
                  }`}>
                    {msg.replyTo && !msg.isRecalled && (
                      <div className={`mb-2 p-2 rounded-xl text-[10px] border-l-2 border-brand-gold bg-black/5 dark:bg-white/5 opacity-80`}>
                        <p className="font-black uppercase tracking-tighter text-[8px] mb-0.5">{msg.replyTo.userName}</p>
                        <p className="italic truncate">{msg.replyTo.text}</p>
                      </div>
                    )}
                    <p className="leading-relaxed">{msg.text}</p>
                    <div className={`flex items-center gap-1.5 mt-1 opacity-50 text-[8px] ${msg.isMe ? 'justify-end' : 'justify-start'}`}>
                      {msg.isEdited && <span>[Đã sửa]</span>}
                      <span>{msg.time}</span>
                    </div>
                    {msg.reaction && (
                      <div className={`absolute -bottom-2 ${msg.isMe ? '-left-1' : '-right-1'} bg-white dark:bg-slate-700 shadow-md border border-brand-gold/30 rounded-full px-1.5 py-0.5 text-[10px] animate-in zoom-in-50`}>
                        {msg.reaction}
                      </div>
                    )}
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
          </>
        )}
      </main>

      {selectedChat && (
        <div className="p-4 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-t border-brand-gold/20 safe-pb z-50">
          {replyingToMessage && (
            <div className="px-4 py-3 mb-3 bg-brand-cream dark:bg-slate-800 rounded-2xl flex items-center justify-between border-l-4 border-brand-gold shadow-sm animate-in slide-in-from-bottom-2">
              <div className="flex-1 pr-4 overflow-hidden">
                <p className="text-[9px] font-black text-brand-red dark:text-brand-gold uppercase">Trả lời {replyingToMessage.isMe ? "chính mình" : selectedChat.userName}</p>
                <p className="text-[10px] text-slate-500 truncate italic">"{replyingToMessage.text}"</p>
              </div>
              <button onClick={() => setReplyingToMessage(null)} className="w-6 h-6 rounded-full bg-brand-red/10 text-brand-red flex items-center justify-center">
                <i className="fa-solid fa-xmark text-xs"></i>
              </button>
            </div>
          )}
          <div className="flex items-center gap-3">
            <button className="text-brand-red"><i className="fa-solid fa-circle-plus text-xl"></i></button>
            <input 
              type="text" 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Aa..."
              className="flex-1 bg-brand-cream dark:bg-slate-800 border border-brand-gold/30 rounded-full px-5 py-3 text-xs font-bold outline-none text-slate-900 dark:text-white placeholder:text-slate-400"
            />
            <button 
              onClick={handleSend}
              className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${inputValue.trim() ? 'bg-brand-red text-brand-gold shadow-md' : 'text-slate-300'}`}
              disabled={!inputValue.trim()}
            >
              <i className={editingMessageId ? "fa-solid fa-check" : "fa-solid fa-paper-plane"}></i>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
