            <span className={`text-[9px] font-black uppercase mt-8 ${activeTab === 'generate' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>Phối đồ</span>
          </div>
          <button onClick={() => setActiveTab('profile')} className={`flex flex-col items-center justify-center gap-1 active:scale-90 transition-all ${activeTab === 'profile' ? 'text-brand-red dark:text-brand-gold' : 'text-slate-400'}`}>
            <i className={`fa-solid fa-user-large text-xl ${activeTab === 'profile' ? 'scale-110' : ''}`}></i>
            <span className="text-[9px] font-black uppercase">Tôi</span>
          </button>
        </div>
      </nav>

      {/* NEW LOADING SCREEN DESIGN */}
      {isGenerating && (
        <div className="fixed inset-0 bg-brand-red dark:bg-slate-950 z-[300] flex flex-col items-center justify-center animate-in fade-in duration-300 px-10 text-center">
          {/* Icon Section (Giữ nguyên theo thiết kế cũ) */}
          <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center mb-8 border-2 border-brand-gold animate-in zoom-in duration-500">
            <i className="fa-solid fa-wand-magic-sparkles text-4xl text-brand-red"></i>
          </div>

          {/* Prominent Title */}
          <h2 className="text-2xl font-black text-brand-goldLight uppercase tracking-[0.1em] mb-3 animate-in slide-in-from-bottom duration-700">
            THIẾT KẾ PHONG CÁCH
          </h2>

          {/* Dynamic Status Text */}
          <div className="h-10 flex items-center justify-center">
            <p className="text-sm font-semibold text-white/90 italic animate-in fade-in duration-1000 key={loadingStatusIdx}">
              {GENERATING_STATUSES[loadingStatusIdx]}
            </p>
          </div>

          {/* Progress Shimmer Line */}
          <div className="w-48 h-1 bg-white/10 rounded-full mt-6 overflow-hidden relative">
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-brand-gold to-transparent w-full animate-[shimmer_2s_infinite]"></div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
      `}</style>
    </div>
  );
};

export default App;

