import React, { useState, useEffect } from 'react';
import { Garment, TravelPlan, Post } from '../types';
import { generateTravelPlan } from '../services/geminiService';
import { TravelSection } from './TravelSection';
import { CreatePostModal } from './CreatePostModal';

interface OutfitResultProps {
  outfit: any;
  top: Garment;
  bottom: Garment;
  savedTravelPlan?: { plan: TravelPlan, sources: any[], city: string };
  onTravelPlanGenerated: (data: { plan: TravelPlan, sources: any[], city: string }) => void;
  onPostPublished: (post: Partial<Post>) => void;
}

const FALLBACK_IMAGE = 'https://images.unsplash.com/photo-1594932224828-b4b059b6f6ee?q=80&w=500&auto=format&fit=crop';

const LOADING_MESSAGES = [
  "Đang thiết lập hành trình thượng lưu...",
  "Tìm kiếm điểm đến đẳng cấp tại địa phương...",
  "Đang chọn lọc tinh hoa ẩm thực...",
  "Sắp xếp phương tiện di chuyển tối ưu...",
  "Hoàn thiện lịch trình dành riêng cho bạn..."
];

export const OutfitResult: React.FC<OutfitResultProps> = ({ 
  outfit, 
  top, 
  bottom, 
  savedTravelPlan,
  onTravelPlanGenerated,
  onPostPublished
}) => {
  const [showCityInput, setShowCityInput] = useState(false);
  const [city, setCity] = useState(savedTravelPlan?.city || '');
  const [isLoadingTravel, setIsLoadingTravel] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);

  useEffect(() => {
    let interval: any;
    if (isLoadingTravel) {
      interval = setInterval(() => {
        setLoadingMsgIdx(prev => (prev + 1) % LOADING_MESSAGES.length);
      }, 2500);
    }
    return () => clearInterval(interval);
  }, [isLoadingTravel]);

  const handleGetTravelPlan = async () => {
    if (!city.trim()) return;
    setIsLoadingTravel(true);
    setLoadingMsgIdx(0);
    try {
      const result = await generateTravelPlan(city, outfit.description, outfit.personality);
      if (result) {
        onTravelPlanGenerated({
          plan: result.plan,
          sources: result.sources,
          city: city
        });
        setShowCityInput(false);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoadingTravel(false);
    }
  };

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    e.currentTarget.src = FALLBACK_IMAGE;
  };

  const allSuggestedLocations = savedTravelPlan 
    ? [...savedTravelPlan.plan.luxury, ...savedTravelPlan.plan.local]
    : [];

  return (
    <div className="space-y-6 w-full h-full">
      {/* LOADING OVERLAY */}
      {isLoadingTravel && (
        <div className="fixed inset-0 bg-brand-red dark:bg-slate-950 z-[200] flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500 overflow-hidden transition-colors">
          <div className="absolute inset-0 opacity-[0.03] dark:opacity-[0.05] pointer-events-none flex flex-wrap gap-20 p-10 items-center justify-center text-white dark:text-brand-gold">
             {[...Array(12)].map((_, i) => (
               <i key={i} className={`fa-solid ${i % 2 === 0 ? 'fa-shirt' : 'fa-plane'} text-[100px] -rotate-12`}></i>
             ))}
          </div>
          <div className="relative z-10 flex flex-col items-center">
            <div className="w-28 h-28 bg-white/5 dark:bg-brand-gold/5 rounded-[3rem] border-2 border-brand-gold flex items-center justify-center mb-12 shadow-[0_0_50px_rgba(212,175,55,0.4)] animate-in zoom-in duration-700">
              <div className="relative">
                <i className="fa-solid fa-compass text-5xl text-brand-gold animate-[spin_4s_linear_infinite]"></i>
              </div>
            </div>
            <div className="space-y-5">
              <h3 className="text-2xl font-black text-brand-goldLight dark:text-brand-gold uppercase tracking-[0.2em] italic">Đang Khởi Hành</h3>
              <p className="text-white/90 dark:text-slate-300 text-sm font-semibold">{LOADING_MESSAGES[loadingMsgIdx]}</p>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl border border-brand-gold/20 animate-in fade-in slide-in-from-bottom-8 duration-700 relative flex flex-col">
        {/* Post Button Floating */}
        <button 
          onClick={() => setIsPostModalOpen(true)}
          className="absolute top-6 right-6 z-20 w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center text-brand-red shadow-2xl border border-brand-gold/30 active:scale-90 transition-all group"
        >
          <i className="fa-solid fa-paper-plane group-hover:animate-bounce"></i>
          <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 translate-y-full text-[8px] font-black text-brand-red dark:text-brand-gold uppercase tracking-tighter opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">Đăng bài</span>
        </button>

        <div className="flex flex-col md:flex-row md:min-h-[400px]">
          {/* Visual Showcase */}
          <div className="p-5 bg-gradient-to-b from-brand-cream to-white dark:from-slate-950 dark:to-slate-900 flex gap-4 transition-colors md:w-1/2">
            <div className="flex-1 aspect-[3/4] bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-brand-gold/10 dark:border-slate-700 p-3 flex items-center justify-center relative group">
              <img src={top?.image} className="w-full h-full object-contain" alt="Top" onError={handleImageError} />
              <div className="absolute top-2 left-2 px-2 py-0.5 bg-brand-red text-white text-[9px] font-black rounded shadow uppercase z-10">ÁO</div>
            </div>
            <div className="flex-1 aspect-[3/4] bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-brand-gold/10 dark:border-slate-700 p-3 flex items-center justify-center relative">
              <img src={bottom?.image} className="w-full h-full object-contain" alt="Bottom" onError={handleImageError} />
              <div className="absolute top-2 left-2 px-2 py-0.5 bg-brand-red text-white text-[9px] font-black rounded shadow uppercase z-10">QUẦN</div>
            </div>
          </div>

          <div className="p-6 pt-2 md:pt-6 space-y-6 md:w-1/2 flex flex-col justify-center">
            <div className="space-y-1">
              <div className="flex flex-wrap items-center gap-2 mb-2">
                <span className="text-[10px] font-black bg-brand-red text-brand-goldLight px-3 py-1 rounded-full uppercase tracking-widest border border-brand-gold/30">Match Score: 98%</span>
                <span className="text-[10px] font-black bg-brand-gold/20 text-brand-red px-3 py-1 rounded-full uppercase tracking-widest italic">Style: {outfit.name}</span>
              </div>
              <h3 className="text-2xl md:text-3xl font-black text-brand-red dark:text-slate-100 leading-none tracking-tighter uppercase">{outfit.name}</h3>
              <p className="text-sm text-slate-600 dark:text-slate-400 font-medium italic border-l-2 border-brand-gold pl-4 py-1 leading-relaxed mb-4">
                "{outfit.description}"
              </p>

              <div className="relative grid grid-cols-2 gap-x-8 pt-6 border-t border-brand-gold/10">
                <div className="absolute left-1/2 top-8 bottom-4 w-[1px] bg-brand-gold/10 -translate-x-1/2"></div>

                {/* Cột Tính cách */}
                <div className="space-y-3">
                  <div className="flex items-center gap-2">
                    <div className="w-5 h-5 rounded-md bg-brand-red/5 dark:bg-brand-gold/5 flex items-center justify-center text-brand-red dark:text-brand-gold">
                      <i className="fa-solid fa-crown text-[8px]"></i>
                    </div>
                    <h4 className="text-[10px] font-black text-brand-red dark:text-brand-gold uppercase tracking-[0.2em]">Tính cách</h4>
                  </div>
                  <p className="text-[11px] font-bold text-slate-700 dark:text-slate-300 leading-relaxed pl-1 italic">
                    {outfit.personality}
                  </p>
                </div>

                {/* Cột Bối cảnh */}
                <div className="space-y-3">
                  <div className="flex items-center gap-2">
                    <div className="w-5 h-5 rounded-md bg-brand-red/5 dark:bg-brand-gold/5 flex items-center justify-center text-brand-red dark:text-brand-gold">
                      <i className="fa-solid fa-map-pin text-[8px]"></i>
                    </div>
                    <h4 className="text-[10px] font-black text-brand-red dark:text-brand-gold uppercase tracking-[0.2em]">Bối cảnh</h4>
                  </div>
                  <div className="flex flex-wrap gap-1.5 pl-1">
                    {outfit.locations && outfit.locations.map((loc: string, i: number) => (
                      <span key={i} className="px-2 py-1 bg-brand-cream dark:bg-slate-800 border border-brand-gold/20 rounded text-[8px] font-black text-brand-red dark:text-slate-400 uppercase tracking-tighter shadow-sm">
                        {loc}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {!savedTravelPlan && (
              <div className="pt-6 border-t border-brand-gold/10 dark:border-slate-800">
                {!showCityInput ? (
                  <button 
                    onClick={() => setShowCityInput(true)}
                    className="w-full py-5 bg-brand-red text-white rounded-[1.5rem] font-black flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl border border-brand-gold/40"
                  >
                    <i className="fa-solid fa-map-location-dot text-brand-gold"></i>
                    KHÁM PHÁ DU LỊCH CÙNG BỘ NÀY
                  </button>
                ) : (
                  <div className="space-y-4 animate-in fade-in zoom-in-95 duration-300">
                    <div className="space-y-1 px-1">
                      <p className="text-[10px] font-black text-brand-gold uppercase tracking-widest">Nhập thành phố dự định ghé thăm</p>
                      <input 
                        type="text" 
                        value={city}
                        onChange={(e) => setCity(e.target.value)}
                        placeholder="Ví dụ: Hà Nội, Đà Lạt..."
                        className="w-full bg-brand-cream dark:bg-slate-800 border-2 border-brand-gold/20 rounded-2xl px-5 py-4 text-sm font-bold text-brand-red focus:border-brand-red outline-none transition-all shadow-inner"
                        autoFocus
                        onKeyDown={(e) => e.key === 'Enter' && handleGetTravelPlan()}
                      />
                    </div>
                    <div className="flex gap-2">
                      <button 
                        onClick={handleGetTravelPlan}
                        disabled={isLoadingTravel || !city.trim()}
                        className="flex-1 py-4 bg-brand-red text-white rounded-2xl font-black active:scale-95 flex items-center justify-center gap-2 shadow-lg border border-brand-gold/30 disabled:opacity-50"
                      >
                        KHỞI HÀNH
                      </button>
                      <button onClick={() => setShowCityInput(false)} className="w-14 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-2xl flex items-center justify-center active:bg-slate-200 transition-colors">
                        <i className="fa-solid fa-xmark"></i>
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {savedTravelPlan && (
        <div className="pb-12 w-full">
          <TravelSection plan={savedTravelPlan.plan} city={savedTravelPlan.city} sources={savedTravelPlan.sources} />
        </div>
      )}

      {/* Post Modal */}
      <CreatePostModal 
        isOpen={isPostModalOpen}
        onClose={() => setIsPostModalOpen(false)}
        topImage={top.image}
        bottomImage={bottom.image}
        suggestedLocations={allSuggestedLocations}
        onPublish={(data) => onPostPublished({ ...data, topImage: top.image, bottomImage: bottom.image })}
      />
    </div>
  );
};

