          <div className="h-10 flex items-center justify-center">
            <p className="text-sm font-semibold text-white/90 italic animate-in fade-in duration-1000">
              {GENERATING_STATUSES[loadingStatusIdx]}
            </p>
          </div>

          <div className="w-48 h-1 bg-white/10 rounded-full mt-6 overflow-hidden relative">
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-brand-gold to-transparent w-full animate-[shimmer_2s_infinite]"></div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
      `}</style>
    </div>
  );
};

