            <span className="text-[9px] font-black uppercase">Tôi</span>
          </button>
        </div>
      </nav>

      {/* LUXURY GENERATING OVERLAY */}
      {isGenerating && (
        <div className="fixed inset-0 bg-brand-red dark:bg-slate-950 z-[400] flex flex-col items-center justify-center px-10 text-center overflow-hidden">
          {/* Background Animated Icons */}
          <div className="absolute inset-0 opacity-[0.05] pointer-events-none flex flex-wrap gap-12 p-10 items-center justify-center">
            {[...Array(15)].map((_, i) => (
              <i key={i} className={`fa-solid ${i % 3 === 0 ? 'fa-shirt' : i % 3 === 1 ? 'fa-scissors' : 'fa-star'} text-[80px] animate-pulse`} style={{ animationDelay: `${i * 0.2}s` }}></i>
            ))}
          </div>

          {/* Scanning Line Effect */}
          <div className="absolute inset-0 z-10 pointer-events-none">
            <div className="w-full h-[2px] bg-gradient-to-r from-transparent via-brand-gold to-transparent shadow-[0_0_20px_#D4AF37] animate-[scan_3s_linear_infinite] absolute top-0"></div>
          </div>

          {/* Main Visual */}
          <div className="relative z-20 flex flex-col items-center w-full max-w-sm">
            <div className="w-28 h-28 bg-white/10 dark:bg-brand-gold/5 rounded-[3rem] border-2 border-brand-gold flex items-center justify-center mb-10 shadow-[0_0_50px_rgba(212,175,55,0.3)] animate-in zoom-in duration-500">
              <div className="relative">
                <i className="fa-solid fa-wand-magic-sparkles text-5xl text-brand-gold animate-pulse"></i>
              </div>
            </div>

            <div className="space-y-6 w-full">
              <div className="space-y-2">
                <h2 className="text-2xl font-black text-brand-goldLight uppercase tracking-[0.2em] italic">PHÒNG THIẾT KẾ</h2>
                <div className="h-6 flex items-center justify-center">
                  <p className="text-sm font-semibold text-white/90 italic animate-in fade-in duration-1000">
                    {GENERATING_STATUSES[loadingStatusIdx]}
                  </p>
                </div>
              </div>

              {/* Simulated Progress Bar */}
              <div className="space-y-2">
                <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden border border-white/5 relative">
                  <div 
                    className="absolute top-0 left-0 h-full bg-brand-gold transition-all duration-300 ease-out shadow-[0_0_15px_rgba(212,175,55,0.6)]"
                    style={{ width: `${genProgress}%` }}
                  ></div>
                </div>
                <div className="flex justify-between items-center px-1">
                  <span className="text-[9px] font-black text-brand-gold/60 uppercase tracking-widest">LuckyDream AI Engine</span>
                  <span className="text-[10px] font-black text-brand-gold uppercase">{Math.round(genProgress)}%</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes scan {
          0% { top: -10%; }
          50% { top: 110%; }
          100% { top: -10%; }
        }
      `}</style>
    </div>
  );
};

export default App;

