      )}

      <CreatePostModal 
        isOpen={isPostModalOpen}
        onClose={() => setIsPostModalOpen(false)}
        topImage={top.image}
        bottomImage={bottom.image}
        suggestedLocations={allSuggestedLocations}
        onPublish={(data) => onPostPublished({ ...data, topImage: top.image, bottomImage: bottom.image })}
      />
    </div>
  );
};

