  {
    id: 'c1',
    userName: 'Thanh Hằng',
    userLevel: 'Elite Fashionista',
    avatar: 'TH',
    lastMessage: 'Áo đó còn size S không bạn nhỉ?',
    messages: [
      { id: 'm1', text: 'Chào Hằng, mình thấy bạn đăng thanh lý set đồ công sở.', time: '10:00', isMe: true },
      { id: 'm3', text: 'Áo đó còn size S không bạn nhỉ?', time: '10:05', isMe: false },
    ]
  }
];

const STYLE_CATEGORIES = [
  { id: 's1', name: 'Thượng lưu', icon: 'fa-crown' },
  { id: 's2', name: 'Tối giản', icon: 'fa-leaf' },
  { id: 's3', name: 'Đường phố', icon: 'fa-bolt' },
  { id: 's4', name: 'Công sở', icon: 'fa-briefcase' },
  { id: 's5', name: 'Hẹn hò', icon: 'fa-heart' },
  { id: 's6', name: 'Cổ điển', icon: 'fa-camera' }
];

const GENERATING_STATUSES = [
  "Đang quét chất liệu vải...",
  "Đang phân tích phom dáng hình học...",
  "Đang kết hợp bảng màu thời thượng...",
  "Đang áp dụng quy tắc tỷ lệ vàng...",
  "Đang hoàn thiện bộ sưu tập riêng cho bạn..."
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'home' | 'generate' | 'profile'>('home');
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [tops, setTops] = useState<Garment[]>([]);
  const [bottoms, setBottoms] = useState<Garment[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [loadingStatusIdx, setLoadingStatusIdx] = useState(0);
  const [result, setResult] = useState<GeminiOutfitResponse | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatContextPost, setChatContextPost] = useState<Post | null>(null);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [travelPlans, setTravelPlans] = useState<Record<number, {plan: TravelPlan, sources: any[], city: string}>>({});
  const [conversations, setConversations] = useState<ChatConversation[]>(INITIAL_CHATS);
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);

  const homeScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  // Xử lý hiệu ứng loading khi tạo outfit
  useEffect(() => {
    let statusInterval: any;

    if (isGenerating) {
      statusInterval = setInterval(() => {
        setLoadingStatusIdx(prev => (prev + 1) % GENERATING_STATUSES.length);
      }, 3000);
    } else {
      setLoadingStatusIdx(0);
    }
    return () => {
      clearInterval(statusInterval);
    };
  }, [isGenerating]);

  const handleOpenChatFromPost = (post: Post) => {
    let existingChat = conversations.find(c => c.userName === post.user.name);
    if (!existingChat) {
      const newChat: ChatConversation = {
        id: `chat-${post.user.name}-${Date.now()}`,
        userName: post.user.name,
        userLevel: post.user.level,
        avatar: post.user.avatar,
        lastMessage: `Xin chào! Mình muốn hỏi về bài đăng ${post.transactionType?.toLowerCase()} của bạn.`,
        messages: [
          { id: 'sys-1', text: `Bạn đang bắt đầu cuộc hội thoại về bài đăng của ${post.user.name}.`, time: 'Bây giờ', isMe: false }
        ]
      };
      setConversations(prev => [...prev, newChat]);
      setActiveChatId(newChat.id);
    } else {
      setActiveChatId(existingChat.id);
    }
    setChatContextPost(post);
    setIsChatOpen(true);
  };

  const handleSendMessage = (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        if (messageIdToEdit) {
          return { ...chat, messages: chat.messages.map(m => m.id === messageIdToEdit ? { ...m, text, isEdited: true } : m) };
        } else {
          const newMessage: Message = { id: Math.random().toString(36).substr(2, 9), text, time: 'Vừa xong', isMe: true, replyTo };
          return { ...chat, lastMessage: text, messages: [...chat.messages, newMessage] };
        }
      }
      return chat;
    }));
  };

  const handleRecallMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => m.id === messageId ? { ...m, text: 'Tin nhắn đã được thu hồi', isRecalled: true, reaction: undefined } : m)
        };
      }
      return chat;
    }));
  };

  const handleDeleteMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.filter(m => m.id !== messageId)
        };
      }
      return chat;
    }));
  };

  const handleReactToMessage = (chatId: string, messageId: string, reaction: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => {
            if (m.id === messageId) {
              return { ...m, reaction: m.reaction === reaction ? undefined : reaction };
            }
            return m;
          })
        };
      }
      return chat;
    }));
  };

  const handlePublishPost = (postData: Partial<Post>) => {
    const newPost: Post = {
      id: `user-${Date.now()}`,
      user: { name: 'Fashionista VN', avatar: 'Me', level: 'Level 1 Discoverer' },
      time: 'Vừa xong',
      description: postData.description || '',
      topImage: postData.topImage || '',
      bottomImage: postData.bottomImage || '',
      location: postData.location || 'LuckyDream Secret',
      tags: postData.tags || [],
      transactionType: postData.transactionType,
      stats: { likes: 0, comments: 0 },
      sampleComments: []
    };

    // Cập nhật danh sách bài đăng (đưa lên đầu)
    setPosts(prev => [newPost, ...prev]);

    // Chuyển hướng về trang chủ
    setActiveTab('home'); 

    // Tự động cuộn lên đầu trang chủ sau một khoảng trễ ngắn để đảm bảo tab đã render
    setTimeout(() => {
      if (homeScrollRef.current) {
        homeScrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
    }, 100);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: GarmentType) => {
    const files = e.target.files;
    if (!files) return;
    (Array.from(files) as File[]).forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newGarment: Garment = { id: Math.random().toString(36).substr(2, 9), type, name: file.name, image: reader.result as string };
        if (type === GarmentType.TOP) setTops(prev => [...prev, newGarment]);
        else setBottoms(prev => [...prev, newGarment]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleGenerate = async () => {
    if (tops.length === 0 || bottoms.length === 0) return;
    setIsGenerating(true);
    try {
      const response = await generateOutfitsFromImages(tops, bottoms);
      if (response) {
        setResult(response);
        setTravelPlans({});
      }
    } catch (err) { console.error(err); }
    finally { 
      setTimeout(() => setIsGenerating(false), 500);
    }
  };

  const myPosts = posts.filter(p => p.user.name === 'Fashionista VN');

  return (
    <div className="flex flex-col h-[100dvh] w-full max-w-xl md:max-w-3xl lg:max-w-5xl mx-auto bg-brand-cream dark:bg-slate-950 relative shadow-2xl overflow-hidden font-sans transition-colors duration-300">
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center justify-between border-b-2 border-brand-gold/40 sticky top-0 z-30 shadow-lg w-full max-w-xl md:max-w-3xl lg:max-w-5xl">
        <h1 className="text-2xl font-black text-brand-goldLight tracking-tighter uppercase italic">LuckyDream</h1>
        <div className="flex items-center gap-2">
           <button 
             onClick={() => { 
               setChatContextPost(null); 
               setActiveChatId(null);
               setIsChatOpen(true); 
             }} 
             className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight border border-brand-gold/40 shadow-inner"
           >
             <i className="fa-solid fa-comment-dots"></i>
           </button>
           <div className="w-9 h-9 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight border border-brand-gold/40 shadow-inner"><i className="fa-solid fa-bell"></i></div>
        </div>
      </header>

      <main className="flex-1 relative overflow-hidden">
        {/* Home Tab */}
        <div 
          ref={homeScrollRef}
          className={`absolute inset-0 overflow-y-auto smooth-scroll scrollbar-hide ${activeTab === 'home' ? 'block' : 'hidden'}`}
        >
          <div className="space-y-6 animate-in fade-in duration-500 pb-24">
            <div className="px-6 pt-6">
              <div className="relative h-48 md:h-64 bg-brand-red dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-8 text-white shadow-xl border-b-4 border-brand-gold/50 flex flex-col justify-center transition-all duration-500">
                <div className="absolute inset-0 z-0 pointer-events-none overflow-hidden">
                  <i className="fa-solid fa-shirt absolute -right-6 -bottom-8 text-[140px] md:text-[200px] text-white opacity-[0.15] dark:opacity-[0.05] rotate-[15deg]"></i>
                </div>
                <div className="relative z-10 space-y-3">
                  <h2 className="text-[28px] md:text-[40px] font-black text-brand-goldLight drop-shadow-md tracking-tight leading-none">Chào Fashionista!</h2>
                  <p className="text-[13px] md:text-[16px] text-white/95 max-w-[240px] md:max-w-md leading-tight font-bold uppercase tracking-wide">Khám phá phong cách thượng lưu của riêng bạn ngay hôm nay.</p>
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between px-7">
                <h3 className="text-[10px] md:text-[12px] font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Khám phá phong cách</h3>
                <span className="text-[9px] md:text-[11px] font-bold text-brand-gold uppercase">Xem thêm</span>
              </div>
              <div className="flex overflow-x-auto gap-4 px-6 pb-2 scrollbar-hide md:justify-center">
                {STYLE_CATEGORIES.map((cat) => (
                  <div key={cat.id} className="flex-shrink-0 flex flex-col items-center gap-2 group cursor-pointer">
                    <div className="w-16 h-16 md:w-20 md:h-20 bg-white dark:bg-slate-900 rounded-3xl border border-brand-gold/20 dark:border-slate-800 flex items-center justify-center text-brand-red dark:text-brand-gold shadow-sm group-active:scale-90 transition-all">
                      <i className={`fa-solid ${cat.icon} text-xl md:text-2xl`}></i>
                    </div>
                    <span className="text-[9px] md:text-[10px] font-black uppercase text-slate-500 dark:text-slate-400 tracking-tighter">{cat.name}</span>
                  </div>
                ))}
              </div>
            </div>

            <section className="space-y-6 px-6 pt-2">
              <div className="flex items-center justify-between px-1">
                <h3 className="text-sm md:text-lg font-black text-brand-red dark:text-slate-100 uppercase tracking-widest">Cộng đồng LuckyDream</h3>
                <div className="flex gap-2">
                   <div className="w-8 h-8 md:w-10 md:h-10 bg-brand-cream dark:bg-slate-800 rounded-xl flex items-center justify-center text-brand-red text-xs border border-brand-gold/20 shadow-sm"><i className="fa-solid fa-filter"></i></div>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {posts.map(post => (
                  <SocialPost key={post.id} post={post} onTransactionClick={() => handleOpenChatFromPost(post)} />
                ))}
              </div>
            </section>
          </div>
        </div>

        {/* Generate Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'generate' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-10">
            {!result ? (
              <>
                <section className="space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="font-black text-brand-red dark:text-slate-200 uppercase text-xs tracking-wider">Áo (Tops)</h3>
                    <label className="text-brand-goldLight bg-brand-red text-[10px] md:text-[12px] font-black px-4 py-2 rounded-full cursor-pointer border border-brand-gold/30">+ THÊM<input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.TOP)} /></label>
                  </div>
                  {tops.length === 0 ? (
                    <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 rounded-[2rem] h-32 md:h-48 flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">Chưa có ảnh áo</div>
                  ) : (
                    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-3">{tops.map(g => <GarmentCard key={g.id} garment={g} onRemove={() => setTops(tops.filter(i => i.id !== g.id))} />)}</div>
                  )}
                </section>
                <section className="space-y-4">
                  <div className="flex items-center justify-between px-1">
                    <h3 className="font-black text-brand-red dark:text-slate-200 uppercase text-xs tracking-wider">Quần & Váy</h3>
                    <label className="text-brand-goldLight bg-brand-red text-[10px] md:text-[12px] font-black px-4 py-2 rounded-full cursor-pointer border border-brand-gold/30">+ THÊM<input type="file" multiple accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, GarmentType.BOTTOM)} /></label>
                  </div>
                  {bottoms.length === 0 ? (
                    <div className="bg-white dark:bg-slate-900 border-2 border-dashed border-brand-gold/20 rounded-[2rem] h-32 md:h-48 flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">Chưa có ảnh quần</div>
                  ) : (
                    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-3">{bottoms.map(g => <GarmentCard key={g.id} garment={g} onRemove={() => setBottoms(bottoms.filter(i => i.id !== g.id))} />)}</div>
                  )}
                </section>
                <button onClick={handleGenerate} disabled={isGenerating || tops.length === 0} className="w-full h-16 bg-brand-red text-brand-goldLight rounded-[1.5rem] font-black shadow-2xl flex items-center justify-center gap-3 border-2 border-brand-gold/40 active:scale-95 transition-all">
                  {isGenerating ? <i className="fa-solid fa-circle-notch animate-spin"></i> : "PHỐI ĐỒ NGAY"}
                </button>
              </>
            ) : (
              <div className="space-y-12 pb-10">
                <div className="flex items-center justify-between px-1">
                   <h3 className="text-xl md:text-3xl font-black text-brand-red dark:text-slate-100 uppercase tracking-tighter">Gợi ý phong cách</h3>
                   <button onClick={() => { setResult(null); setTravelPlans({}); }} className="text-[10px] md:text-[12px] font-black text-white bg-brand-red px-4 py-2 rounded-full border border-brand-gold/30 uppercase">Làm lại</button>
                </div>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
                  {result.outfits.map((outfit, idx) => (
                    <OutfitResult 
                      key={idx} 
                      outfit={outfit} 
                      top={tops[outfit.topIndex]} 
                      bottom={bottoms[outfit.bottomIndex]} 
                      savedTravelPlan={travelPlans[idx]}
                      onTravelPlanGenerated={(data) => setTravelPlans(prev => ({...prev, [idx]: data}))}
                      onPostPublished={handlePublishPost}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Profile Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'profile' ? 'block' : 'hidden'}`}>
          <div className="space-y-8 animate-in slide-in-from-left-4 duration-500 pb-10 max-w-2xl mx-auto">
            <div className="flex flex-col items-center py-8 space-y-4">
              <div className="w-24 h-24 md:w-32 md:h-32 bg-brand-red rounded-[2.5rem] flex items-center justify-center text-3xl md:text-5xl text-brand-gold border-4 border-brand-gold/30 shadow-2xl relative">
                <i className="fa-solid fa-user-ninja"></i>
              </div>
              <div className="text-center">
                <h2 className="text-xl md:text-2xl font-black text-brand-red dark:text-slate-100 uppercase tracking-tight">Fashionista VN</h2>
                <p className="text-[10px] md:text-[12px] font-bold text-brand-gold uppercase tracking-[0.2em] bg-brand-red px-3 py-1 rounded-full inline-block mt-2">Level 1 Discoverer</p>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 px-1">
              <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between shadow-sm transition-colors md:col-span-2">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-indigo-50 dark:bg-indigo-900/30 rounded-xl flex items-center justify-center text-indigo-600 shadow-inner">
                    <i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i>
                  </div>
                  <span className="font-bold text-brand-red dark:text-slate-200">Giao diện tối</span>
                </div>
                <button onClick={() => setIsDarkMode(!isDarkMode)} className={`w-12 h-6 rounded-full transition-all relative ${isDarkMode ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isDarkMode ? 'left-7' : 'left-1'}`}></div>
                </button>
              </div>

              {[
                { label: 'Địa điểm đã lưu', icon: 'fa-bookmark', color: 'text-amber-500', bgColor: 'bg-amber-50 dark:bg-amber-900/20' },
                { label: 'Cài đặt tài khoản', icon: 'fa-gear', color: 'text-blue-600', bgColor: 'bg-blue-50 dark:bg-blue-900/20' },
                { label: 'Trợ giúp & Phản hồi', icon: 'fa-circle-question', color: 'text-brand-red', bgColor: 'bg-brand-red/5 dark:bg-brand-red/10' }
              ].map((item, i) => (
                <div key={i} className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-brand-gold/20 dark:border-slate-800 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 ${item.bgColor} rounded-xl flex items-center justify-center ${item.color} shadow-inner`}>
                      <i className={`fa-solid ${item.icon}`}></i>
                    </div>
                    <span className="font-bold text-brand-red dark:text-slate-200">{item.label}</span>
                  </div>
                  <i className="fa-solid fa-chevron-right text-[10px] text-brand-gold/70"></i>
                </div>
              ))}
            </div>

            <section className="space-y-6 pt-6">
              <div className="flex items-center justify-between px-1">
                <h3 className="text-sm md:text-lg font-black text-brand-red dark:text-slate-100 uppercase tracking-widest flex items-center gap-3">
                  <i className="fa-solid fa-clock-rotate-left text-brand-gold"></i>
                  Lịch sử bài đăng của bạn
                </h3>
                <span className="text-[10px] font-black text-brand-gold uppercase">{myPosts.length} BÀI</span>
              </div>

              {myPosts.length === 0 ? (
