               <div className="absolute -bottom-2 left-1/2 w-3 h-3 bg-brand-gold rounded-full shadow-[0_0_15px_#D4AF37] animate-ping" style={{ animationDelay: '1s' }}></div>
            </div>

            <div className="space-y-8 max-w-xs">
