              {/* Status Message with Glitch/Fade Effect */}
              <div className="h-14 flex items-center justify-center overflow-hidden">
                <p className="text-base font-bold text-white uppercase tracking-wider drop-shadow-md animate-in fade-in slide-in-from-bottom-2 duration-500">
                  {GENERATING_STATUSES[loadingStatusIdx]}
