              </div>

              {/* INFINITE PROGRESS BAR */}
              <div className="space-y-4">
                <div className="w-full h-2.5 bg-brand-dark/30 rounded-full overflow-hidden border border-brand-gold/20 relative shadow-inner">
                  {/* The Infinite Runner */}
                  <div className="absolute top-0 bottom-0 left-[-100%] w-full bg-gradient-to-r from-transparent via-brand-gold to-transparent animate-[shimmer_1.5s_infinite] shadow-[0_0_20px_#D4AF37]"></div>
                  {/* Decorative static segments */}
                  <div className="absolute inset-0 flex justify-between px-2">
                    {[...Array(12)].map((_, i) => (
                      <div key={i} className="h-full w-[1px] bg-white/10"></div>
                    ))}
                  </div>
                </div>
                <div className="flex justify-between items-center px-2">
                  <span className="text-[9px] font-black text-brand-gold/60 uppercase tracking-[0.3em] flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-pulse"></span>
                    Synthesizing
                  </span>
                  <span className="text-[9px] font-black text-brand-gold/60 uppercase tracking-[0.3em]">AI-Powered</span>
                </div>
              </div>
            </div>
          </div>

          {/* Footer Decor */}
          <div className="absolute bottom-12 flex flex-col items-center gap-4 opacity-50">
             <div className="flex items-center gap-6">
               <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-ping"></div>
               <div className="w-1.5 h-1.5 bg-white rounded-full animate-ping" style={{ animationDelay: '0.3s' }}></div>
               <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-ping" style={{ animationDelay: '0.6s' }}></div>
             </div>
             <p className="text-[10px] font-black text-brand-goldLight/80 uppercase tracking-[0.5em] italic">Luxury Fashion Ecosystem VN</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

