              {/* CLEAN INFINITE PROGRESS BAR (No segments) */}
              <div className="space-y-4">
                <div className="w-full h-1 bg-brand-dark/20 rounded-full overflow-hidden border-none relative bg-white/5 shadow-inner">
                  {/* The Infinite Runner Light */}
                  <div className="absolute top-0 bottom-0 left-[-100%] w-full bg-gradient-to-r from-transparent via-brand-gold to-transparent animate-[shimmer_1.8s_infinite] shadow-[0_0_10px_#D4AF37]"></div>
                </div>
                <div className="flex justify-center items-center gap-3">
                  <span className="w-1 h-1 bg-brand-gold rounded-full animate-ping"></span>
                  <span className="text-[10px] font-black text-brand-gold/50 uppercase tracking-[0.35em]">
                    Đang xử lý dữ liệu AI
                  </span>
                  <span className="w-1 h-1 bg-brand-gold rounded-full animate-ping" style={{ animationDelay: '0.5s' }}></span>
                </div>
              </div>
            </div>
          </div>

          {/* Footer Decor */}
          <div className="absolute bottom-10 opacity-40">
             <p className="text-[11px] font-black text-brand-goldLight/70 uppercase tracking-[0.45em] italic drop-shadow-sm">LuckyDream Luxury Edition</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

