                <p className="text-base font-bold text-white uppercase tracking-[0.1em] drop-shadow-md animate-in fade-in duration-500">
                  {GENERATING_STATUSES[loadingStatusIdx]}
                </p>
              </div>

              {/* CLEAN INFINITE PROGRESS BAR */}
              <div className="space-y-5">
                <div className="w-full h-[2px] bg-white/5 rounded-full overflow-hidden border-none relative bg-white/5">
                  {/* The Infinite Runner Light */}
                  <div className="absolute top-0 bottom-0 left-[-100%] w-full bg-gradient-to-r from-transparent via-brand-gold/80 to-transparent animate-[shimmer_2s_infinite] shadow-[0_0_12px_#D4AF37]"></div>
                </div>

                {/* Secondary Status Info - Changed to user requested text */}
                <div className="flex justify-center items-center gap-4">
                  <span className="w-1 h-1 bg-brand-gold rounded-full animate-ping opacity-60"></span>
                  <span className="text-[10px] font-black text-brand-gold/60 uppercase tracking-[0.45em] drop-shadow-sm">
                    LUCKY DREAM OUTFIT
                  </span>
                  <span className="w-1 h-1 bg-brand-gold rounded-full animate-ping opacity-60" style={{ animationDelay: '1s' }}></span>
                </div>
              </div>
            </div>
          </div>

          {/* Footer Decor */}
          <div className="absolute bottom-12 opacity-30 text-center">
             <p className="text-[10px] font-black text-brand-goldLight/70 uppercase tracking-[0.55em] italic">LuckyDream Luxury Ecosystem</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

