                    <OutfitResult key={idx} outfit={outfit} top={tops[outfit.topIndex]} bottom={bottoms[outfit.bottomIndex]} savedTravelPlan={travelPlans[idx]} onTravelPlanGenerated={(data) => setTravelPlans(prev => ({...prev, [idx]: data}))} onPostPublished={handlePublishPost} />
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Profile Tab */}
        <div className={`absolute inset-0 overflow-y-auto px-6 pt-6 pb-24 smooth-scroll scrollbar-hide ${activeTab === 'profile' ? 'block' : 'hidden'}`}>
