              </div>

              <div className="space-y-6">
                <div className="w-full h-[2px] bg-white/10 rounded-full overflow-hidden border-none relative">
                  <div className="absolute top-0 bottom-0 left-[-100%] w-full bg-gradient-to-r from-transparent via-brand-gold to-transparent animate-[shimmer_2s_infinite] shadow-[0_0_15px_#D4AF37]"></div>
                </div>

                <div className="flex justify-center items-center gap-4">
                  <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-ping opacity-70"></div>
                  <span className="text-[11px] font-black text-brand-gold/70 uppercase tracking-[0.5em] drop-shadow-md">
                    LUCKY DREAM OUTFIT
                  </span>
                  <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-ping opacity-70" style={{ animationDelay: '1s' }}></div>
                </div>
              </div>
            </div>
          </div>

          {/* Footer Decor */}
          <div className="absolute bottom-12 opacity-30 text-center w-full px-10">
             <p className="text-[10px] font-black text-brand-goldLight/70 uppercase tracking-[0.6em] italic whitespace-nowrap">Luxury Fashion Ecosystem</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

