  "Đang tinh chỉnh phong cách riêng của bạn..."
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'home' | 'generate' | 'profile'>('home');
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [tops, setTops] = useState<Garment[]>([]);
  const [bottoms, setBottoms] = useState<Garment[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [loadingStatusIdx, setLoadingStatusIdx] = useState(0);
  const [result, setResult] = useState<GeminiOutfitResponse | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatContextPost, setChatContextPost] = useState<Post | null>(null);
  const [activeChatId, setSelectedChatId] = useState<string | null>(null);
  const [travelPlans, setTravelPlans] = useState<Record<number, {plan: TravelPlan, sources: any[], city: string}>>({});
  const [conversations, setConversations] = useState<ChatConversation[]>(INITIAL_CHATS);
  const [posts, setPosts] = useState<Post[]>(MOCK_POSTS);
  const [selectedHistoryPost, setSelectedHistoryPost] = useState<Post | null>(null);

  const homeScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    let statusInterval: any;
    if (isGenerating) {
      statusInterval = setInterval(() => {
        setLoadingStatusIdx(prev => (prev + 1) % GENERATING_STATUSES.length);
      }, 2500);
    } else {
      setLoadingStatusIdx(0);
    }
    return () => clearInterval(statusInterval);
  }, [isGenerating]);

  if (!currentUser) {
    return <AuthView onLoginSuccess={(user) => setCurrentUser(user)} />;
  }

  const handleOpenChatFromPost = (post: Post) => {
    let existingChat = conversations.find(c => c.userName === post.user.name);
    if (!existingChat) {
      const newChat: ChatConversation = {
        id: `chat-${post.user.name}-${Date.now()}`,
        userName: post.user.name,
        userLevel: post.user.level,
        avatar: post.user.avatar,
        lastMessage: `Xin chào! Mình muốn hỏi về bài đăng ${post.transactionType?.toLowerCase()} của bạn.`,
        messages: [
          { id: 'sys-1', text: `Bạn đang bắt đầu cuộc hội thoại về bài đăng của ${post.user.name}.`, time: 'Bây giờ', isMe: false }
        ]
      };
      setConversations(prev => [...prev, newChat]);
      setSelectedChatId(newChat.id);
    } else {
      setSelectedChatId(existingChat.id);
    }
    setChatContextPost(post);
    setIsChatOpen(true);
  };

  const handleSendMessage = (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        if (messageIdToEdit) {
          return { ...chat, messages: chat.messages.map(m => m.id === messageIdToEdit ? { ...m, text, isEdited: true } : m) };
        } else {
          const newMessage: Message = { id: Math.random().toString(36).substr(2, 9), text, time: 'Vừa xong', isMe: true, replyTo };
          return { ...chat, lastMessage: text, messages: [...chat.messages, newMessage] };
        }
      }
      return chat;
    }));
  };

  const handleRecallMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => m.id === messageId ? { ...m, text: 'Tin nhắn đã được thu hồi', isRecalled: true, reaction: undefined } : m)
        };
      }
      return chat;
    }));
  };

  const handleDeleteMessage = (chatId: string, messageId: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.filter(m => m.id !== messageId)
        };
      }
      return chat;
    }));
  };

  const handleReactToMessage = (chatId: string, messageId: string, reaction: string) => {
    setConversations(prev => prev.map(chat => {
      if (chat.id === chatId) {
        return {
          ...chat,
          messages: chat.messages.map(m => {
            if (m.id === messageId) {
              return { ...m, reaction: m.reaction === reaction ? undefined : reaction };
            }
            return m;
          })
        };
      }
      return chat;
    }));
  };

  const handlePublishPost = (postData: Partial<Post>) => {
    const newPost: Post = {
      id: `user-${Date.now()}`,
      user: { name: currentUser.name, avatar: currentUser.avatar, level: currentUser.level },
      time: 'Vừa xong',
      description: postData.description || '',
      topImage: postData.topImage || '',
      bottomImage: postData.bottomImage || '',
      location: postData.location || 'LuckyDream Secret',
      tags: postData.tags || [],
      transactionType: postData.transactionType,
      stats: { likes: 0, comments: 0 },
      sampleComments: []
    };

    setPosts(prev => [newPost, ...prev]);
    setActiveTab('home'); 
    setTimeout(() => {
      if (homeScrollRef.current) {
        homeScrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
    }, 100);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: GarmentType) => {
    const files = e.target.files;
    if (!files) return;
    (Array.from(files) as File[]).forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newGarment: Garment = { id: Math.random().toString(36).substr(2, 9), type, name: file.name, image: reader.result as string };
        if (type === GarmentType.TOP) setTops(prev => [...prev, newGarment]);
        else setBottoms(prev => [...prev, newGarment]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleGenerate = async () => {
    if (tops.length === 0 || bottoms.length === 0) return;
    setIsGenerating(true);
    try {
      const response = await generateOutfitsFromImages(tops, bottoms);
      if (response) {
        setResult(response);
        setTravelPlans({});
      }
    } catch (err) { console.error(err); }
    finally { 
      setTimeout(() => setIsGenerating(false), 500);
    }
  };

  const myPosts = posts.filter(p => p.user.name === currentUser.name);

  return (
