const SLIDES = [
  {
    title: "AI FASHION STYLIST",
    subtitle: "Trí tuệ nhân tạo phối đồ",
    description: "Sử dụng Gemini AI để phân tích tủ đồ của bạn và đưa ra những gợi ý phối đồ thời thượng nhất.",
