                onClick={() => { setData({...data, theme: 'dark'}); onThemeChange(true); }}
                className={`p-6 rounded-[2.5rem] border-2 flex flex-col items-center gap-3 transition-all ${data.theme === 'dark' ? 'bg-slate-900 border-brand-gold shadow-2xl scale-105' : 'bg-slate-800 border-transparent opacity-60'}`}
              >
                <div className="w-12 h-12 bg-indigo-900/50 text-indigo-400 rounded-full flex items-center justify-center">
                  <i className="fa-solid fa-moon text-2xl"></i>
                </div>
                <span className="text-[10px] font-black uppercase text-brand-gold">Dark Mode</span>
              </button>
            </div>
            <button 
              onClick={finish}
              className="w-full py-5 bg-brand-red text-brand-goldLight rounded-2xl font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all border border-brand-gold/30"
            >
              Hoàn tất thiết lập
            </button>
          </div>
        )}
      </div>

      <div className="text-[8px] font-black text-slate-400 uppercase tracking-[0.5em]">
        Tailored Experience by Gemini
      </div>
    </div>
  );
};

