  try {
    const ai = getAI();

    // Gửi kèm thông tin định danh để AI hiểu ngữ cảnh số lượng
    const topParts = tops.map((g, index) => ([
      { text: `[ÁO SỐ ${index}] - Tên file: ${g.name}` },
      {
        inlineData: {
          data: cleanBase64(g.image),
          mimeType: "image/jpeg",
        }
      }
    ])).flat();

    const bottomParts = bottoms.map((g, index) => ([
      { text: `[QUẦN/VÁY SỐ ${index}] - Tên file: ${g.name}` },
      {
        inlineData: {
          data: cleanBase64(g.image),
          mimeType: "image/jpeg",
        }
      }
    ])).flat();

    const prompt = `
      Bạn là một "Senior Fashion Stylist" chuyên nghiệp cho giới thượng lưu Việt Nam.
      Tôi đã cung cấp cho bạn ${tops.length} mẫu áo và ${bottoms.length} mẫu quần/váy từ tủ đồ của tôi.

      NHIỆM VỤ:
      1. Phân tích phong cách, màu sắc, chất liệu của từng món đồ qua ảnh.
      2. Phối hợp chúng thành 3 bộ cánh (outfits) xuất sắc nhất, tuân thủ các quy tắc thời trang (phối màu tương phản/tương đồng, cân bằng tỷ lệ).
      3. Đặt tên cho từng outfit theo phong cách sang trọng.
      4. Giải thích tại sao bộ phối này lại đẹp và phù hợp với tính cách nào.

      LƯU Ý QUAN TRỌNG: 
      - topIndex và bottomIndex PHẢI khớp với số thứ tự tôi đã đánh dấu (0 đến n-1).
      - Trả về kết quả ĐỊNH DẠNG JSON nguyên khối.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [
        {
          parts: [
            ...topParts,
            ...bottomParts,
            { text: prompt }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            outfits: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  topIndex: { type: Type.INTEGER, description: "Chỉ số của áo trong danh sách tops" },
                  bottomIndex: { type: Type.INTEGER, description: "Chỉ số của quần trong danh sách bottoms" },
                  name: { type: Type.STRING, description: "Tên phong cách của bộ đồ" },
                  description: { type: Type.STRING, description: "Mô tả chi tiết cách phối" },
                  personality: { type: Type.STRING, description: "Tính cách người mặc phù hợp" },
                  locations: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING },
                    description: "Các địa điểm phù hợp để diện bộ đồ này"
                  }
                },
                required: ["topIndex", "bottomIndex", "name", "description", "personality", "locations"]
              }
            }
          },
          required: ["outfits"]
        }
      }
    });

    const parsed = extractJson(response.text || "{}");
    if (!parsed || !parsed.outfits) return null;

    // Lọc bỏ các index sai (nếu có)
    const safeOutfits = parsed.outfits.filter((o: any) => 
      o.topIndex >= 0 && o.topIndex < tops.length && 
      o.bottomIndex >= 0 && o.bottomIndex < bottoms.length
    );

    return { outfits: safeOutfits };
  } catch (error) {
    console.error("Lỗi Gemini Stylist:", error);
    return null;
  }
};

export const generateTravelPlan = async (
  city: string,
  outfitDescription: string,
  vibe: string
): Promise<{plan: TravelPlan, sources: any[]} | null> => {
  try {
    const ai = getAI();
    const prompt = `
      Tôi đang ở thành phố "${city}" và mặc bộ đồ có mô tả: "${outfitDescription}" (Vibe: ${vibe}).
      Sử dụng Google Search để tìm các địa điểm du lịch, quán cafe, nhà hàng sang trọng hoặc độc bản tại ${city} phù hợp với bộ đồ này.
      Trả về JSON chi tiết về hành trình Luxury và Local.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    const parsed = extractJson(response.text || "{}");
    if (!parsed) return null;

    return {
      plan: parsed as TravelPlan,
      sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  } catch (error) {
    console.error("Lỗi Travel Plan:", error);
    return null;
  }
};

