import { GoogleGenAI, Type } from "@google/genai";
import { Garment, GeminiOutfitResponse, TravelPlan } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const cleanBase64 = (base64: string) => {
  if (base64.includes(',')) {
    return base64.split(',')[1];
  }
  return base64;
};

const extractJson = (text: string) => {
  try {
    return JSON.parse(text);
  } catch (e) {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        return JSON.parse(jsonMatch[0]);
      } catch (innerE) {
        console.error("Không thể parse khối JSON:", innerE);
      }
    }
    return null;
  }
};

export const generateOutfitsFromImages = async (
  tops: Garment[],
  bottoms: Garment[]
): Promise<GeminiOutfitResponse | null> => {
  try {
    const ai = getAI();

    const topParts = tops.map((g, index) => ([
      { text: `Áo số ${index + 1}:` },
      {
        inlineData: {
          data: cleanBase64(g.image),
          mimeType: "image/jpeg",
        }
      }
    ])).flat();

    const bottomParts = bottoms.map((g, index) => ([
      { text: `Quần/Váy số ${index + 1}:` },
      {
        inlineData: {
          data: cleanBase64(g.image),
          mimeType: "image/jpeg",
        }
      }
    ])).flat();

    const prompt = `
      Bạn là một chuyên gia thời trang. Hãy phân tích các hình ảnh áo và quần/váy tôi gửi.
      Hãy phối hợp chúng thành 3 bộ đồ (outfit) đẹp nhất.
      Đối với mỗi bộ đồ, hãy cho biết:
      - topIndex: vị trí của áo trong danh sách áo (bắt đầu từ 0)
      - bottomIndex: vị trí của quần trong danh sách quần (bắt đầu từ 0)
      - name: tên phong cách bộ đồ
      - description: mô tả tại sao lại phối như vậy
      - personality: tính cách phù hợp
      - locations: các địa điểm nên diện bộ này.

      Trả về kết quả dưới dạng JSON theo cấu trúc: { "outfits": [...] }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            ...topParts,
            ...bottomParts,
            { text: prompt }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    return extractJson(text);
  } catch (error) {
    console.error("Lỗi phối đồ:", error);
    return null;
  }
};

export const generateTravelPlan = async (
  city: string,
  outfitDescription: string,
  vibe: string
): Promise<{plan: TravelPlan, sources: any[]} | null> => {
  try {
    const ai = getAI();
    const prompt = `Tôi đang ở ${city} và mặc bộ đồ: ${outfitDescription}. Hãy gợi ý lịch trình du lịch và ăn uống phù hợp.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    const text = response.text;
    const parsed = extractJson(text);
    if (!parsed) return null;

    return {
      plan: parsed as TravelPlan,
      sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  } catch (error) {
