export default App;

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { ChatConversation, Message, Post } from '../types';

interface ChatPanelProps {
  isOpen: boolean;
  onClose: () => void;
  conversations: ChatConversation[];
  initialChatId?: string | null;
  contextPost?: Post | null;
  onSendMessage: (chatId: string, text: string, messageIdToEdit?: string, replyTo?: Message['replyTo']) => void;
  onRecallMessage: (chatId: string, messageId: string) => void;
  onDeleteMessage: (chatId: string, messageId: string) => void;
  onReactToMessage: (chatId: string, messageId: string, reaction: string) => void;
}

const REACTIONS = ['❤️', '🔥', '👍', '😂', '😮', '😢'];

export const ChatPanel: React.FC<ChatPanelProps> = ({ 
  isOpen, onClose, conversations, initialChatId, contextPost,
  onSendMessage, onRecallMessage, onDeleteMessage, onReactToMessage 
}) => {
  const [selectedChatId, setSelectedChatId] = useState<string | null>(null);
  const [inputValue, setInputValue] = useState('');
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [replyingToMessage, setReplyingToMessage] = useState<Message | null>(null);
  const [contextMenu, setContextMenu] = useState<{ x: number, y: number, msg: Message } | null>(null);
  const [showScrollButton, setShowScrollButton] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const prevMessagesCountRef = useRef<number>(0);
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const selectedChat = conversations.find(c => c.id === selectedChatId) || null;
  const currentMessages = selectedChat?.messages || [];

  useEffect(() => {
    if (isOpen) {
      setSelectedChatId(initialChatId || null);
    }
  }, [isOpen, initialChatId]);

  useLayoutEffect(() => {
    if (!selectedChatId || !scrollContainerRef.current) return;
    const container = scrollContainerRef.current;
    const isNewChat = prevMessagesCountRef.current === 0;
    const isNearBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 150;
    if (isNewChat || isNearBottom) {
      scrollToBottom('smooth');
    }
    prevMessagesCountRef.current = currentMessages.length;
  }, [currentMessages.length, selectedChatId]);

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  const handleScroll = () => {
    if (!scrollContainerRef.current) return;
    const container = scrollContainerRef.current;
    setShowScrollButton(container.scrollHeight - container.scrollTop - container.clientHeight > 300);
  };

  if (!isOpen) return null;

  const handleSend = () => {
    if (!inputValue.trim() || !selectedChatId) return;
    let replyData: Message['replyTo'] | undefined;
    if (replyingToMessage) {
      replyData = {
        userName: replyingToMessage.isMe ? "Tôi" : (selectedChat?.userName || "Người dùng"),
        text: replyingToMessage.text
      };
    }
    onSendMessage(selectedChatId, inputValue.trim(), editingMessageId || undefined, replyData);
    setInputValue('');
    setEditingMessageId(null);
    setReplyingToMessage(null);
  };

  const handleStartPress = (e: React.MouseEvent | React.TouchEvent, msg: Message) => {
    if (msg.isRecalled) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    longPressTimer.current = setTimeout(() => {
      setContextMenu({ x: clientX, y: clientY, msg });
    }, 500);
  };

  const handleEndPress = () => {
    if (longPressTimer.current) clearTimeout(longPressTimer.current);
  };

  const getMenuStyles = () => {
    if (!contextMenu) return {};
    const screenWidth = window.innerWidth;
    const screenHeight = window.innerHeight;
    let left = contextMenu.x - 110;
    let top = contextMenu.y - 150;
    if (left + 220 > screenWidth - 16) left = screenWidth - 220 - 16;
    if (left < 16) left = 16;
    if (top + 320 > screenHeight - 100) top = screenHeight - 320 - 100;
    return { top, left };
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col bg-brand-cream dark:bg-slate-950 animate-in slide-in-from-right duration-500">
      {/* Context Menu Overlay */}
      {contextMenu && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setContextMenu(null)}>
          <div 
            className="absolute bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-brand-gold/30 p-1 min-w-[220px] animate-in zoom-in-95 duration-200"
            style={getMenuStyles()}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex justify-between items-center gap-1 p-5 mb-1 bg-slate-50 dark:bg-slate-800/50 rounded-t-[2.4rem]">
              {REACTIONS.map(r => (
                <button key={r} onClick={() => { onReactToMessage(selectedChatId!, contextMenu.msg.id, r); setContextMenu(null); }} className="text-2xl hover:scale-125 active:scale-90 transition-transform duration-200">
                  {r}
                </button>
              ))}
            </div>
            <div className="flex flex-col p-2 space-y-1">
              {[
                { label: 'Trả lời', icon: 'fa-reply', act: () => { setReplyingToMessage(contextMenu.msg); setEditingMessageId(null); } },
                ...(contextMenu.msg.isMe && !contextMenu.msg.isRecalled ? [
                    { label: 'Chỉnh sửa', icon: 'fa-pen-to-square', act: () => { setInputValue(contextMenu.msg.text); setEditingMessageId(contextMenu.msg.id); } },
                    { label: 'Thu hồi', icon: 'fa-rotate-left', act: () => onRecallMessage(selectedChatId!, contextMenu.msg.id) }
                ] : []),
                { label: 'Xóa', icon: 'fa-trash-can', act: () => onDeleteMessage(selectedChatId!, contextMenu.msg.id), danger: true }
              ].map((item, idx) => (
                <button key={idx} onClick={() => { item.act(); setContextMenu(null); }} className={`flex items-center justify-between px-5 py-4 text-[10px] font-black uppercase rounded-2xl transition-colors ${item.danger ? 'text-red-500 hover:bg-red-50 dark:hover:bg-red-950/20' : 'text-brand-red dark:text-brand-gold hover:bg-slate-50 dark:hover:bg-slate-800'}`}>
                  {item.label} <i className={`fa-solid ${item.icon} opacity-50`}></i>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center gap-4 border-b-2 border-brand-gold/40 shadow-xl relative z-[50]">
        <button onClick={selectedChat ? () => setSelectedChatId(null) : onClose} className="w-10 h-10 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight shadow-inner active:scale-90 transition-all">
          <i className={`fa-solid ${selectedChat ? 'fa-chevron-left' : 'fa-xmark'}`}></i>
        </button>
        <div className="flex-1">
          <h2 className="text-lg font-black text-brand-goldLight uppercase tracking-tight leading-none mb-1">{selectedChat ? selectedChat.userName : 'Hộp thư đẳng cấp'}</h2>
          {selectedChat && (
            <div className="flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                <p className="text-[8px] text-brand-gold/60 font-black uppercase tracking-widest">{selectedChat.userLevel} • Trực tuyến</p>
            </div>
          )}
        </div>
        {selectedChat && (
            <button className="w-10 h-10 bg-white/10 rounded-full flex items-center justify-center text-brand-goldLight border border-white/5 active:scale-95"><i className="fa-solid fa-phone"></i></button>
        )}
      </header>

      {/* Content Area */}
      <main 
        ref={scrollContainerRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto scrollbar-hide relative flex flex-col bg-brand-cream/30 dark:bg-slate-950"
      >
        {!selectedChat ? (
          <div className="p-6 space-y-3 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="px-1 mb-6">
                <h3 className="text-xs font-black text-brand-red dark:text-slate-400 uppercase tracking-[0.2em]">Cuộc hội thoại gần đây</h3>
            </div>
            {conversations.length > 0 ? conversations.map(chat => (
              <button key={chat.id} onClick={() => setSelectedChatId(chat.id)} className="w-full bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] flex items-center gap-4 border border-brand-gold/10 dark:border-slate-800 active:scale-[0.98] transition-all shadow-sm hover:border-brand-gold/40">
                <div className="w-14 h-14 bg-brand-red rounded-[1.3rem] flex items-center justify-center text-brand-gold text-lg font-black border border-brand-gold/30 shadow-xl">{chat.avatar}</div>
                <div className="flex-1 text-left overflow-hidden">
                  <div className="flex justify-between items-center mb-1">
                    <h4 className="font-black text-brand-red dark:text-slate-100 uppercase text-xs tracking-tight">{chat.userName}</h4>
                    <span className="text-[8px] text-slate-400 font-bold uppercase">{chat.messages.length > 0 ? chat.messages[chat.messages.length - 1].time : ''}</span>
                  </div>
                  <p className="text-[10px] text-slate-500 dark:text-slate-400 truncate font-bold leading-tight italic">"{chat.lastMessage}"</p>
                </div>
              </button>
            )) : (
                <div className="h-[50dvh] flex flex-col items-center justify-center text-center opacity-20 p-10 space-y-4">
                    <i className="fa-solid fa-mailbox text-6xl text-brand-red"></i>
