            <i className="fa-solid fa-paper-plane text-xs"></i>
          </button>
        </div>

        <div className="flex flex-col md:flex-row">
          {/* Visual Showcase (Refined) */}
          <div className="p-6 bg-brand-cream/30 dark:bg-slate-950/50 md:w-2/5 flex flex-col gap-3">
            <div className="relative aspect-[3/4] bg-white dark:bg-slate-900 rounded-[2rem] shadow-inner border border-brand-gold/10 p-3 group/img overflow-hidden">
