            </div>

            {!savedTravelPlan && (
              <div className="pt-6">
                {!showCityInput ? (
                  <button 
                    onClick={() => setShowCityInput(true)}
                    className="w-full py-5 bg-brand-red text-brand-goldLight rounded-[1.8rem] font-black flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl border border-brand-gold/30 hover:shadow-brand-gold/20"
                  >
                    <i className="fa-solid fa-earth-asia"></i>
                    TÌM HÀNH TRÌNH DU LỊCH
                  </button>
                ) : (
                  <div className="space-y-4 animate-in zoom-in-95 duration-300">
                    <input 
