import React, { useState, useEffect, useRef } from 'react';
import { ChatConversation, Message, Post } from '../types';

interface ChatPanelProps {
  isOpen: boolean;
  onClose: () => void;
  conversations: ChatConversation[];
  initialChatId?: string | null;
  contextPost?: Post | null;
  onSendMessage: (chatId: string, text: string) => void;
  onRecallMessage: (chatId: string, messageId: string) => void;
  onDeleteMessage: (chatId: string, messageId: string) => void;
  onReactToMessage: (chatId: string, messageId: string, reaction: string) => void;
}

export const ChatPanel: React.FC<ChatPanelProps> = ({ 
  isOpen, onClose, conversations, initialChatId,
  onSendMessage
}) => {
  const [selectedChatId, setSelectedChatId] = useState<string | null>(null);
  const [inputValue, setInputValue] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const selectedChat = conversations.find(c => c.id === selectedChatId) || null;
  const currentMessages = selectedChat?.messages || [];

  useEffect(() => {
    if (isOpen) {
      setSelectedChatId(initialChatId || null);
    }
  }, [isOpen, initialChatId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentMessages.length]);

  if (!isOpen) return null;

  const handleSend = () => {
    if (!inputValue.trim() || !selectedChatId) return;
    onSendMessage(selectedChatId, inputValue.trim());
    setInputValue('');
  };

  return (
    <div className="fixed inset-0 z-[100] flex flex-col bg-brand-cream dark:bg-slate-950 animate-in slide-in-from-right duration-500">
      <header className="bg-brand-red dark:bg-slate-900 px-6 pt-12 pb-5 flex items-center gap-4 border-b-2 border-brand-gold/40 shadow-xl">
        <button onClick={selectedChat ? () => setSelectedChatId(null) : onClose} className="w-10 h-10 bg-brand-gold/20 rounded-full flex items-center justify-center text-brand-goldLight">
          <i className={`fa-solid ${selectedChat ? 'fa-chevron-left' : 'fa-xmark'}`}></i>
        </button>
        <h2 className="text-lg font-black text-brand-goldLight uppercase tracking-tight">{selectedChat ? selectedChat.userName : 'Tin nhắn'}</h2>
      </header>

      <main className="flex-1 overflow-y-auto p-6 space-y-4">
        {!selectedChat ? (
          <div className="space-y-3">
            {conversations.map(chat => (
              <button key={chat.id} onClick={() => setSelectedChatId(chat.id)} className="w-full bg-white dark:bg-slate-900 p-4 rounded-2xl flex items-center gap-4 border border-brand-gold/10">
                <div className="w-12 h-12 bg-brand-red rounded-xl flex items-center justify-center text-brand-gold font-black">{chat.avatar}</div>
                <div className="flex-1 text-left">
                  <h4 className="font-black text-brand-red dark:text-slate-100 uppercase text-xs">{chat.userName}</h4>
                  <p className="text-[10px] text-slate-500 truncate italic">"{chat.lastMessage}"</p>
                </div>
              </button>
            ))}
          </div>
        ) : (
          <div className="space-y-4">
            {currentMessages.map(msg => (
              <div key={msg.id} className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-4 rounded-2xl text-xs font-medium shadow-sm ${msg.isMe ? 'bg-brand-red text-white' : 'bg-white dark:bg-slate-900 text-slate-800 dark:text-slate-200'}`}>
                  {msg.text}
                  <p className="text-[8px] opacity-50 mt-1 text-right">{msg.time}</p>
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>
        )}
      </main>

      {selectedChat && (
        <div className="p-6 bg-white dark:bg-slate-900 border-t border-brand-gold/20 safe-pb">
          <div className="flex gap-3">
            <input 
              type="text" 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Nhập tin nhắn..."
              className="flex-1 bg-slate-50 dark:bg-slate-800 border-2 border-brand-gold/10 rounded-xl px-4 py-2 text-xs outline-none"
            />
            <button onClick={handleSend} className="w-10 h-10 bg-brand-red text-brand-goldLight rounded-xl flex items-center justify-center">
              <i className="fa-solid fa-paper-plane"></i>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Garment, TravelPlan, Post } from '../types';
import { generateTravelPlan } from '../services/geminiService';
import { TravelSection } from './TravelSection';
import { CreatePostModal } from './CreatePostModal';

interface OutfitResultProps {
  outfit: any;
  top: Garment;
  bottom: Garment;
  savedTravelPlan?: { plan: TravelPlan, sources: any[], city: string };
  onTravelPlanGenerated: (data: { plan: TravelPlan, sources: any[], city: string }) => void;
  onPostPublished: (post: Partial<Post>) => void;
}

const FALLBACK_IMAGE = 'https://images.unsplash.com/photo-1594932224828-b4b059b6f6ee?q=80&w=500&auto=format&fit=crop';

export const OutfitResult: React.FC<OutfitResultProps> = ({ 
  outfit, 
  top, 
  bottom, 
  savedTravelPlan,
  onTravelPlanGenerated,
  onPostPublished
}) => {
  const [showCityInput, setShowCityInput] = useState(false);
  const [city, setCity] = useState(savedTravelPlan?.city || '');
  const [isLoadingTravel, setIsLoadingTravel] = useState(false);
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);

  const handleGetTravelPlan = async () => {
    if (!city.trim()) return;
    setIsLoadingTravel(true);
    try {
      const result = await generateTravelPlan(city, outfit.description, outfit.personality);
      if (result) {
        onTravelPlanGenerated({ plan: result.plan, sources: result.sources, city });
        setShowCityInput(false);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoadingTravel(false);
    }
  };

  const allSuggestedLocations = savedTravelPlan 
    ? [...savedTravelPlan.plan.luxury, ...savedTravelPlan.plan.local]
    : [];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="bg-white dark:bg-slate-900 rounded-3xl overflow-hidden shadow-xl border border-brand-gold/10">
        <div className="flex flex-col md:flex-row">
          <div className="p-4 bg-brand-cream dark:bg-slate-800 md:w-1/3 flex gap-2">
            <img src={top?.image || FALLBACK_IMAGE} className="w-1/2 md:w-full aspect-[3/4] object-contain rounded-xl bg-white" alt="Top" />
            <img src={bottom?.image || FALLBACK_IMAGE} className="w-1/2 md:w-full aspect-[3/4] object-contain rounded-xl bg-white" alt="Bottom" />
          </div>
          <div className="p-6 md:w-2/3 space-y-4">
            <h3 className="text-xl font-black text-brand-red dark:text-brand-gold uppercase italic">{outfit.name}</h3>
            <p className="text-xs text-slate-600 dark:text-slate-400 italic">"{outfit.description}"</p>
            <div className="flex flex-wrap gap-2 pt-2">
              <span className="bg-brand-red/10 text-brand-red text-[8px] font-black px-3 py-1 rounded-full uppercase">{outfit.personality}</span>
              {outfit.locations && outfit.locations.map((loc: string, i: number) => (
                <span key={i} className="bg-slate-100 dark:bg-slate-800 text-slate-400 text-[8px] font-black px-3 py-1 rounded-full uppercase">{loc}</span>
              ))}
            </div>
            {!savedTravelPlan && (
              <div className="pt-4">
                {!showCityInput ? (
                  <button onClick={() => setShowCityInput(true)} className="w-full py-3 bg-brand-red text-brand-goldLight rounded-xl font-black text-[10px] uppercase tracking-widest">Tìm hành trình du lịch</button>
                ) : (
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      value={city}
                      onChange={(e) => setCity(e.target.value)}
                      placeholder="Thành phố?"
                      className="flex-1 bg-slate-50 dark:bg-slate-800 border border-brand-gold/20 rounded-xl px-4 py-2 text-xs outline-none"
                    />
                    <button onClick={handleGetTravelPlan} disabled={isLoadingTravel} className="px-4 bg-brand-red text-white rounded-xl text-[10px] font-black">
                      {isLoadingTravel ? '...' : 'GO'}
                    </button>
                  </div>
                )}
              </div>
            )}
            <button onClick={() => setIsPostModalOpen(true)} className="w-full py-3 border border-brand-red text-brand-red rounded-xl font-black text-[10px] uppercase">Chia sẻ lên cộng đồng</button>
          </div>
        </div>
      </div>

      {savedTravelPlan && <TravelSection plan={savedTravelPlan.plan} city={savedTravelPlan.city} sources={savedTravelPlan.sources} />}

      <CreatePostModal 
        isOpen={isPostModalOpen}
        onClose={() => setIsPostModalOpen(false)}
        topImage={top.image}
        bottomImage={bottom.image}
        suggestedLocations={allSuggestedLocations}
        onPublish={(data) => onPostPublished({ ...data, topImage: top.image, bottomImage: bottom.image })}
      />
    </div>
  );
};

